/*******************************************************************//**
PURPOSE: Default SmFace Constructor

NOTES:
***********************************************************************/
SmFace::SmFace()
 : m_pFU             (NULL),
   m_bRectangularTrim(UNSURE), 
   m_pSurface        (NULL) 
   //, m_bSwapUVInOrient(FALSE)
{
  SM_OLDTOL_LINE m_sZoneTol3d = 0.0 ;

  // report construction at SmObject::Notify level - skip other levels
  SmObject::Notify(SM_NO_CONSTRUCTION, this, NULL, NULL);

} // end SmFace::SmFace Default Constructor

/*******************************************************************//**
PURPOSE: Destructor for the face - it cleans up the surface

NOTES:
***********************************************************************/
SmFace::~SmFace()
{
  // Notify DESTRUCTION behavior
  //  SmFace::Notify()     - case SM_NO_DESTRUCTION: does nothing
  //  SmTopology::Notify() - case SM_NO_DESTRUCTION: does nothing
  //  SmAObject::Notify()  - case SM_NO_DESTRUCTION: for every attr{pAttr->Destruction();}
  //  SmObject::Notify()   - case SM_NO_DESTRUCTION: report through UserCallback
  Notify(SM_NO_DESTRUCTION, this, NULL, NULL);

  m_pFU = NULL ;

  // If there is a surface and I own it then delete it.
  if (m_pSurface && m_pSurface->GetOwner() == this)
    { delete m_pSurface; m_pSurface = NULL ; } 

} // end SmFace::~SmFace destructor

// This object automatically calls the initilization and termination of the GW nurb volume stack.
class SmNLibStackHandler 
{
  private:
    NL_STACKS * m_pStacks;
  public:
    SmNLibStackHandler(NL_STACKS * pStacks) { m_pStacks = pStacks; N_InitNurbs(m_pStacks); }
   ~SmNLibStackHandler()                 { N_EndNurbs(m_pStacks); }
} ; // end class SmNLibStackHandler


