/*******************************************************************//**
PURPOSE: Static helper for ComputeLoopOrientation(): See whether the current step
   is crossing a seam, and deal with it.

NOTES:
   Assumes that the point-dropping routine will step across seams,
   so that sUV1 and sUV2 will be on opposite sides of it.

   If a shift happens, sUV1 will be shifted to be in the same period as sUV2.
   (That fits in with the calling algorithm.)

   If no shift happens, rParamShift will be unchanged.
***********************************************************************/
static SmBoolean sm_CheckSeamCrossing
(SmPoint2d        & sUV1,        // i/o: previous uv point, possibly shifted by a period 
 SmPoint2d        & sUV2,        // in : current uv point 
 const SmSurface  * pSurf,       // NotUsed: in : the surface being walked 
 const SmExtent2d & rDomain,     // in : domain of pSurf 
 SmBoolean          bClosedU,    // in : Is the surface closed in U? 
 SmBoolean          bClosedV,    // in : Is the surface closed in V? 
 SmVector2d       & rParamShift) // i/o]: If we are across a seam, add this to the uv point for the area calculation 
{
  SM_REF1(pSurf) ;
  SmBoolean bRet = FALSE;

  if ( ! bClosedU && ! bClosedV )
    { return SM_SUCCESS; }


  if ( bClosedU )
  {
      SmExtent1d sIvl( rDomain.GetUInterval() );
      double dPeriod = sIvl.GetLength();
      double dJump = sUV2.x - sUV1.x;

      // The caller is stepping along the curve in 0.05 increments.
      if ( smos_Fabs( dJump ) > 0.90 * dPeriod )
      {
          if ( sUV2.x < sUV1.x )
            {
              // Jumped from high end to low.
              rParamShift.x += dPeriod;
              sUV1.x -= dPeriod;  // Bring prev pt into same period as curr pt.
            }
          else
            {
              // Jumped from low end to high.
              rParamShift.x -= dPeriod;
              sUV1.x += dPeriod;
            }

          bRet = TRUE;
      }
  }

  if ( bClosedV )
  {
      SmExtent1d sIvl( rDomain.GetVInterval() );
      double dPeriod = sIvl.GetLength();
      double dJump = sUV2.y - sUV1.y;

      // The caller is stepping along the curve in 0.05 increments.
      if ( smos_Fabs( dJump ) > 0.90 * dPeriod )
      {
          if ( sUV2.y < sUV1.y )
            {
              // Jumped from high end to low.
              rParamShift.y += dPeriod;
              sUV1.y -= dPeriod;
            }
          else
            {
              // Jumped from low end to high.
              rParamShift.y -= dPeriod;
              sUV1.y += dPeriod;
            }

          bRet = TRUE;
      }
  }


/* 
  if ( ! rDomain.IsPoint2dOnBoundary( sUV2 ) )
    { return SM_SUCCESS; }

  if ( bClosedU && ! sIvl.ContainsValue( sUV2.x, -SM_EFF_ZERO ) ) // neg tol: on-bdry returns False.
  {
      double dLim = sIvl.GetMin() + SM_EFF_ZERO;
      if ( sUV2.x <= dLim  &&  sUV1.x > dLim ) // Pushing low-u boundary
        {
          rParamShift += sIvl;
          bRet = TRUE;
        }

      dLim = sIvl.GetMax() - SM_EFF_ZERO;
      if ( sUV2.x >= dLim  &&  sUV1.x < dLim ) // Pushing high-u boundary
        {
          rParamShift -= sIvl;
          bRet = TRUE;
        }
  }

  ... repeat for V.
*/ 


  return bRet;

}  // end sm_CheckSeamCrossing

/*******************************************************************//**
PURPOSE: Replace a nonSmBSpline face->surface with an SmBSpline Surface approximation

NOTES: When face->Surface is replaced, the old surface and all the face->UVTrimCurves are deleted.
       When Face->Surface is already a kindof SmBSplineSurface
       takes no action and returns SM_SUCCESS.
***********************************************************************/
SmStatus SmFace::ApproximateWithBSpline
(
  double   dApproxTol3d,   // in : maximum allowed distance between Approx and original surfaces 
  double & dAchievedTol3d  // out: actual max distance between approx and original surfaces 
)
{
  // init output
  dAchievedTol3d = 0.0 ;

  // no work - no surface or surface is a kindof SmBSplineSurface
  if(   GetSurface() == NULL
     || GetSurface()->IsKindOf(SmBSplineSurface_TYPE))
    {
      // all done
      return(SM_SUCCESS) ;
    }

  // locals
  ULONG ii ;
  SmStatus sRtn = SM_SUCCESS ;
  const SmContext     * cpContext = GetContext() ;
  SmSurface           * pSurface  = GetSurface() ;
  SmBSplineSurface    * pNewBSplineSurface = NULL ;
  SmTArray<SmEdge *>    sEdges ;
  SmTArray<SmVertex *>  sVertices ;
// Remove Composites
//  SmCFace             * pCFace = GetCompositeFaceOwner() ;
  SmPoint2d             sUVPoint ;

#ifdef SM_DEBUG_CODE
SmBoolean bDebugMe = FALSE ;
#endif // SM_DEBUG_CODE

  // Offset Surfaces
  if(pSurface->IsKindOf(SmOffsetSurface_TYPE)) 
    {
      SmOffsetSurface * pOffsetSurface = ((SmOffsetSurface*)pSurface) ;
      const SmSurface * pBaseSurface   = pOffsetSurface->GetBaseSurface() ;
      double            dOffsetDist    = pOffsetSurface->GetOffsetDistance() ;

      if(pBaseSurface->IsKindOf(SmBSplineSurface_TYPE))
        {
          SmBSplineSurface *pBSplineSurface = (SmBSplineSurface*)pBaseSurface ;
          pBSplineSurface->ApproximateOffsetSurface(*cpContext, dOffsetDist, dApproxTol3d, pNewBSplineSurface) ;
                                                                          
         } // end BAseSurface is a BSpline check
     } // end OffsetSurface check

  // low work - surface shape and orientation can be handled by special cases
  if(pNewBSplineSurface == NULL)
    {
      sRtn = pSurface->MakeExactBSplineIfPossible(pNewBSplineSurface) ; 
    }

  // when pSurface could not be mapped to an exact BSplineSuface - approximate one
  if(pNewBSplineSurface == NULL)
    {
// Remove Composites - moved block up from below
      GetEdges(sEdges) ;
      GetVertices(sVertices) ;

// Remove Composites
//      // gather Face (or CFace edges and vertices
//      if(pCFace) { pCFace->GetEdges(sEdges) ;
//                 pCFace->GetVertices(sVertices) ;
//               }
//      else       { GetEdges(sEdges) ;
//                 GetVertices(sVertices) ;
//               }

      // presize locals
      ULONG ip = 0, ic = 0 ;
      ULONG lPtCnt  = sVertices.GetSize() ;
      ULONG lCrvCnt = sEdges.GetSize() ;

#ifdef SM_DEBUG_CODE
double dThisGap, dPreMaxGap = 0.0, dPostMaxGap = 0.0 ;
      // draw 
      if(bDebugMe)
        {
          ULONG di ;
          SmPoint3d sPt ; 
          SmTArray<SmEdgeuse*>   sDEdgeuses ; 
          SmTArray<SmVertex*>    sDVertices ; 
          SmTArray<SmVertexuse*> sDVertexuses ;
          SM_DUMP_AND_ASSERT_VALID(pSurface) ;
          SM_DUMP_AND_ASSERT_VALID(this) ;

          SmFace *pFace = this ;
          SmBrep *pBrep = pFace ? pFace->GetBrep() : NULL ;

          smgfx_Erase() ;
          for(di=0;di<sVertices.GetSize();di++)
            { smgfx_SetLook(5,6, 1,0,0) ; sVertices[di]->Draw() ; sm_GraphicsLoop() ; }

          for(di=0;di<sEdges.GetSize();di++)
            { sEdges[di]->GetEdgeuses(sDEdgeuses) ; sEdges[di]->GetVertices(sDVertices) ; sEdges[di]->GetVertexuses(sDVertexuses) ; 
              smgfx_SetLook(3,4, 1,0,0) ; sEdges[di]->Draw() ; sm_GraphicsLoop() ; 
              smgfx_SetLook(4,5, 1,0,0) ; sEdges[di]->DrawParams() ; sm_GraphicsLoop() ;
              smgfx_SetLook(7,8, 0,1,0) ; sDVertices[0]->Draw() ; sm_GraphicsLoop() ;
              smgfx_SetLook(7,8, 0,0,1) ; sDVertices[1]->Draw() ; sm_GraphicsLoop() ;
              smgfx_SetLook(3,4, .2,.8,.1) ; { sDEdgeuses[0]->Draw() ; sm_GraphicsLoop() ;
                                               if(sDEdgeuses[0]->GetUVTrimCurve())
                                                 { SmCrvOnSurf sCrvOnSurf(*sDEdgeuses[0]->GetUVTrimCurve(),*pSurface) ;
                                                   sCrvOnSurf.DrawParams() ; sm_GraphicsLoop() ; 
                                             }   }
              smgfx_SetLook(3,4, .2,.8,.1) ; { sDEdgeuses[1]->Draw() ; sm_GraphicsLoop() ;
                                               if(sDEdgeuses[1]->GetUVTrimCurve())
                                                 { SmCrvOnSurf sCrvOnSurf(*sDEdgeuses[1]->GetUVTrimCurve(),*pSurface) ;
                                                   sCrvOnSurf.DrawParams() ; sm_GraphicsLoop() ; 
                                             }   } 
              smgfx_SetLook(3,4, .2,.8,.1) ; { sDEdgeuses[2]->Draw() ; sm_GraphicsLoop() ;
                                               if(sDEdgeuses[2]->GetUVTrimCurve())
                                                 { SmCrvOnSurf sCrvOnSurf(*sDEdgeuses[2]->GetUVTrimCurve(),*pSurface) ;
                                                   sCrvOnSurf.DrawParams() ; sm_GraphicsLoop() ; 
                                             }   }
              smgfx_SetLook(3,4, .2,.8,.1) ; { sDEdgeuses[3]->Draw() ; sm_GraphicsLoop() ;
                                               if(sDEdgeuses[3]->GetUVTrimCurve())
                                                 { SmCrvOnSurf sCrvOnSurf(*sDEdgeuses[3]->GetUVTrimCurve(),*pSurface) ;
                                                   sCrvOnSurf.DrawParams() ; sm_GraphicsLoop() ; 
                                             }   } 
            }
          smgfx_SetLook(1,2, 0,0,1) ; if(pBrep) pBrep->Draw(TRUE) ; sm_GraphicsLoop() ;
          smgfx_SetLook(1,2, 0,1,1) ; if(pSurface) pSurface->DrawUV(8,8,FALSE,NULL,TRUE) ; sm_GraphicsLoop() ;
          smgfx_SetLook(4,5, 0,1,1) ; if(pSurface) pSurface->DrawParams() ; sm_GraphicsLoop() ;
          smgfx_SetLook(1,2, 0,0,0) ; if(pFace) pFace->Draw(SM_DM_CROSSHATCH) ; sm_GraphicsLoop() ;
          sm_GraphicsLoop() ;
        }
#endif // SM_DEBUG_CODE

      // declare presized ApproximateConstrainedSurface() input arrays
      SmTArray<SmPoint3d>        s3DTrimPoints(lPtCnt,  NULL, lPtCnt) ;   // in : optional array of 3d Point constraints, NULL to ignore, default:[NULL]
      SmTArray<SmPoint2d>        sUVTrimPoints(lPtCnt,  NULL, lPtCnt) ;   // in : associated surface UVPoints made close to each 3DTrimPoint, NULL to ignore, default:[NULL] 
      SmTArray<SmCurve *>        s3DTrimCurves(lCrvCnt, NULL, lCrvCnt) ;  // in : optional array of 3d Curve constraints, NULL to ignore, default:[NULL]
      SmTArray<SmBSplineCurve *> sUVTrimCurves(lCrvCnt, NULL, lCrvCnt) ;  // in : associated UVTrimCurve for each given 3d Curve, NULL to ignore, default:[NULL]
      SmTArray<SmExtent1d>       sTrimIntervals(lCrvCnt, NULL, lCrvCnt) ; // in : associated trim intervals for each given 3d Curve, NULL to ignore, default:[NULL]

      // for every vertex - add vertex xyz, uv, values to ApproximateConstrainedSurface() input arrays
      for(ii=0;ii<lPtCnt;ii++)
        {
          SmVertex *pVertex = sVertices[ii] ;

          // Get Vertexuse between Face and Vertex
          SmVertexuse *pVertexuse = pVertex->GetVertexuseOfFace(this) ;
          if(pVertexuse == NULL)
            { continue ; }
      
          // Get UVPoint for vertexuse  
          sRtn = pVertexuse->ComputeUVPoint(sUVPoint) ;
          if(sRtn != SM_SUCCESS)
            { continue ; }

          // set values
          s3DTrimPoints.SetAt(ii, pVertex->GetPoint() ) ;
          sUVTrimPoints.SetAt(ii, sUVPoint ) ; 

          // increment the smp array indices
          ip++ ;

#ifdef SM_DEBUG_CODE
          // check pre gaps
          if(bDebugMe)
            {
              SmPoint3d sTestPoint ;
              pSurface->EvaluatePoint(sUVTrimPoints[ii], sTestPoint) ;
              dThisGap = sTestPoint.DistanceBetween(s3DTrimPoints[ii]) ; 
              if(dThisGap > dPreMaxGap) { dPreMaxGap = dThisGap ; }
            }
#endif // SM_DEBUG_CODE

        } // end iter ii, every vertex bulding NLib input sample arrays

      // set Point array final sizes
      if(ip != lPtCnt)
        {
          s3DTrimPoints.SetSize(ip) ;
          sUVTrimPoints.SetSize(ip) ;
        }

      // for every edge - add 3DCurve, UVCurve, and Interval data to ApproximateConstrainedSurface() input arrays
      for(ii=0;ii<sEdges.GetSize();ii++)
        {
          SmEdge         * pEdge        = sEdges[ii] ;
          SmCurve        * pCurve       = pEdge->GetCurve() ;
          SmBSplineCurve * pUVTrimCurve = pEdge->GetUVTrimCurveOfSurface(pSurface) ;
          SmExtent1d       sIvl         = pEdge->GetInterval() ;

          // skip problem elements
          if(pUVTrimCurve == NULL)
            { continue ; }

          // set values
          s3DTrimCurves.SetAt (ii, pCurve) ;      
          sUVTrimCurves.SetAt (ii, pUVTrimCurve) ;
          sTrimIntervals.SetAt(ii, sIvl) ;        

          // increment the smp array indices
          ic++ ;

        } // end iter every edge computing the perimter length

      // set curve array final sizes
      if(ic != lCrvCnt)
        {
          s3DTrimCurves.SetSize(ic) ;
          sUVTrimCurves.SetSize(ic) ;
          sTrimIntervals.SetSize(ic) ;
        }

#ifdef SM_DEBUG_CODE
      // draw 
      if(bDebugMe)
        {
          ULONG di ;
          SmPoint3d sPt ; 
          SM_DUMP_AND_ASSERT_VALID(pSurface) ;
          SM_DUMP_AND_ASSERT_VALID(this) ;

          SmFace *pFace = this ;
          SmBrep *pBrep = pFace ? pFace->GetBrep() : NULL ;

          smgfx_Erase() ;
          smgfx_SetLook(1,2, 0,0,1) ; if(pBrep) pBrep->Draw(TRUE) ; sm_GraphicsLoop() ;
          smgfx_SetLook(1,2, 0,1,1) ; if(pSurface) pSurface->DrawUV(8,8,FALSE,NULL,TRUE) ; sm_GraphicsLoop() ;
          smgfx_SetLook(1,2, 0,0,0) ; if(pFace) pFace->Draw(SM_DM_CROSSHATCH) ; sm_GraphicsLoop() ;
          for(di=0;di<s3DTrimPoints.GetSize();di++)
            { smgfx_SetLook(3,4, 1,0,0) ; s3DTrimPoints[di].Draw() ; sm_GraphicsLoop() ;
              smgfx_SetLook(5,6, 0,0,1) ; if(pSurface) { pSurface->EvaluatePoint(sUVTrimPoints[di], sPt) ; sPt.Draw() ; sm_GraphicsLoop() ; }
            }
          for(di=0;di<s3DTrimCurves.GetSize();di++)
            { smgfx_SetLook(3,4, 1,0,0) ; s3DTrimCurves[di]->Draw(&sTrimIntervals[di]) ; sm_GraphicsLoop() ;
              smgfx_SetLook(5,6, 0,0,1) ; if(pSurface) { SmCrvOnSurf sCrv(*sUVTrimCurves[di], *pSurface) ; sCrv.Draw(&sTrimIntervals[di]) ; sm_GraphicsLoop() ; }
            }
          sm_GraphicsLoop() ;
        }
#endif // SM_DEBUG_CODE

      // Build the approximation Surface 
      sRtn = SM_ERR;
      sRtn = pSurface->ApproximateSurface(*cpContext,          // in : context for new object construction
                                           dApproxTol3d,       // in : max allowed approximation distance
                                           dAchievedTol3d,     // out: Max tolerance achieved.
                                           5,                  // in : How many times to split spans before giving up
                                                               //      Splits this many times in each direction (u/v).
                                           pNewBSplineSurface, // out: approx surf with the smallest number of 
                                                               //      subdivisions possible within tol of exact surf.
                                                               //      NULL = finest allowed subdivision surf still out of tol
                                           FALSE) ;            // in : TRUE = if this Surface is a BSpline just copy it
                                                               //      FALSE= approximate the surface
                                                               //      default:[FALSE]
    if(pNewBSplineSurface == NULL)
      {
        // Build the approximation surface
        sRtn = pSurface->ApproximateConstrainedSurface
                          (*cpContext,           // in : context for new object construction
                            dApproxTol3d,        // in : maximum allowed distance between Approx and original surfaces
                            dAchievedTol3d,      // out: actual max distance between approx and original surfaces     
                            pNewBSplineSurface,  // out: The new surface when successful, else NULL.
                                                 //      expected to be NULL on input - otherwise can cause a memory leak
                           &s3DTrimPoints,       // in : optional array of 3d Point constraints, NULL to ignore, default:[NULL]
                           &sUVTrimPoints,       // in : associated surface UVPoints made close to each 3DTrimPoint, NULL to ignore, default:[NULL] 
                           &s3DTrimCurves,       // in : optional array of 3d Curve constraints, NULL to ignore, default:[NULL]
                           &sUVTrimCurves,       // in : associated UVTrimCurve for each given 3d Curve, NULL to ignore, default:[NULL]
                           &sTrimIntervals) ;    // in : associated trim intervals for each given 3d Curve, NULL to ignore, default:[NULL]
      }

#ifdef SM_DEBUG_CODE
    if(bDebugMe)
      {
        ULONG di ;

        for(di=0;di<sUVTrimPoints.GetSize();di++)
          {
            // check post gaps
            SmPoint3d sTestPoint ;
            pSurface->EvaluatePoint(sUVTrimPoints[ii], sTestPoint) ;
            dThisGap = sTestPoint.DistanceBetween(s3DTrimPoints[ii]) ; 
            if(dThisGap > dPostMaxGap) { dPostMaxGap = dThisGap ; }
          }
      }
#endif // SM_DEBUG_CODE

    } // end couldn't convert to an exact BSpline check

  // when ApproximateConstrainedSurface worked
  if(sRtn == SM_SUCCESS && pNewBSplineSurface != NULL)
    {
      // swap the face's surface - delete appropriate objects (old surface and UVTrimCurves)
      SmBrep* pBrep = GetBrep();
      pBrep->ReplaceSurface( this, pNewBSplineSurface, FALSE, NULL, FALSE );
    }
  else // ApproximateConstrainedSurface failed
    {
      if(pNewBSplineSurface) { delete pNewBSplineSurface ; pNewBSplineSurface = NULL ; }
    }

#ifdef SM_DEBUG_CODE
  // draw 
  if(bDebugMe)
    {
      ULONG di ;
      SmTArray<SmLoop*> dsLoops ; GetLoops(dsLoops) ;
      SmFace *pFace = this ;
      SmBrep *pBrep = pFace ? pFace->GetBrep() : NULL ;

      SM_DUMP_AND_ASSERT_VALID(pBrep) ;
      SM_DUMP_AND_ASSERT_VALID(pNewBSplineSurface) ;
      SM_DUMP_AND_ASSERT_VALID(this) ;

      smgfx_Erase() ;
      smgfx_SetLook(1,2, 0,0,1) ; if(pBrep) pBrep->Draw(TRUE) ; sm_GraphicsLoop() ;
      smgfx_SetLook(1,2, 0,1,1) ; if(pNewBSplineSurface) pNewBSplineSurface->DrawUV(8,8,FALSE,NULL,TRUE) ; sm_GraphicsLoop() ;
      smgfx_SetLook(1,2, 0,1,1) ; if(pNewBSplineSurface) pNewBSplineSurface->DrawParams() ; sm_GraphicsLoop() ;
      smgfx_SetLook(1,2, 0,1,1) ; if(pNewBSplineSurface) pNewBSplineSurface->DrawVectorField(pNewBSplineSurface->GetNaturalUVDomain(),5,5,SM_DM_UNIT_NORMAL) ; sm_GraphicsLoop() ;
      smgfx_SetLook(1,2, 0,0,0) ; if(pFace) pFace->Draw(SM_DM_CROSSHATCH) ; sm_GraphicsLoop() ;
      smgfx_SetLook(4,5, 0,1,0) ; for(di=0;di<dsLoops.GetSize();di++) { if(dsLoops[di]) dsLoops[di]->Draw(3,FALSE,NULL,FALSE) ; sm_GraphicsLoop() ; }
      sm_GraphicsLoop() ;
    }
#endif // SM_DEBUG_CODE

  // all done 
  return(SM_SUCCESS) ;

} // end SmFace::ApproximateWithBSpline

/*******************************************************************//**
PURPOSE: Build an Approximate BSplineSurface to the current
         Face->Surface with new parameterization 

NOTES: This function is good for replacing current face->Surfaces
       with BSplineSurfaces which is good for preparing a Brep
       for Export and for rebuilding problem surfaces.

RETURNS: SM_SUCCESS when approximate surface build is okay,
         SM_ERR     when surface build fails
***********************************************************************/
SmStatus SmFace::ApproximateSurface
 (SmBSplineSurface *& rpNewBSplineSurface, // out: New Surf if possible 
  SmBoolean           bReplaceSurf)        // in : TRUE=replace and delete Curr Surf, FALSE = don't 
{
  SM_REF1(bReplaceSurf) ;

  // init output
  rpNewBSplineSurface = NULL ;

  // locals
  const ULONG lSmpCnt_U = 9 ;  // Samples lSmpCnt_U+1 from Normalized 0.0 to 1.0
  const ULONG lSmpCnt_V = 9 ;  // Samples lSmpCnt_V+1 from Normalized 0.0 to 1.0

  // locals
  SmSurface       * pSurface     = GetSurface() ;
  const SmContext * cpContext    = GetContext() ;
  SmExtent2d        sUVDomain    = pSurface->GetNaturalUVDomain() ;
  SmXSectTol3d     sXSectTol3d  = 100 * SmTol::GetXSectTol3d(pSurface,pSurface) ; // use Surface for Tol, not Faces and Edges because this is a Surface approximation function
  SmZoneTol3d      sZoneTol3d   = SmTol::GetZoneTol3d(this) ;
  SmApproxTol3d    sApproxTol3d = SmTol::GetApproxTol3d(pSurface) ;

  // check state - no context - no Fix - return assertion failure
  AERN_MSG(cpContext != NULL, SM_ERR_ASSERT_FAILURE, _T("SmFace::ApproximateSurface: Face->GetContext() == NULL, No Surface approximation possible")) ;

  // New Surface specification locals
  ULONG lUDegree = 3 ;
  ULONG lVDegree = 3 ;
  ULONG lMaxUCtrlPnts = smos_Max( (lSmpCnt_U + 1)/2 - 1, 5) ;
  ULONG lMaxVCtrlPnts = smos_Max( (lSmpCnt_V + 1)/2 - 1, 5) ;
SmBSplineSurface * pNewSurf            = NULL ;
SmAxis2Placement * pOptProjectionPlane = NULL ;

  // Sample locals
  ULONG ii, jj, lSmpCnt_Crv = 2 * lSmpCnt_U ;
  SmPoint2d sUV, sUVLast ;
  SmPoint3d sPt, sDu, sDv, sCrvPt ;
  SmBoolean bSuccess ;
  double    dGap, dAngRad ;
  SmBoolean bIsMulti;

  SM_OBJ_ARRAY(sPoints,  SmPoint3d,  (lSmpCnt_U+1) * (lSmpCnt_V+1)) ;
  SM_OBJ_ARRAY(sNormals, SmVector3d, (lSmpCnt_U+1) * (lSmpCnt_V+1)) ;
  SM_PTR_ARRAY(sEdges, SmEdge, 16) ;
// Remove Composites
//   SM_PTR_ARRAY(sFaces, SmFace, 16) ;

  // for composites gather all the faces
  // SmCFace *pCFace = GetCompositeFaceOwner() ;
  // if(pCFace) { pCFace->GetFaces(sFaces) ;
  //          }
  // else       { sFaces.Add(this) ;
  //          }
  // 
  // // for face or every composite face
  // for(ii=0;ii<sFaces.GetSize();ii++)
  //   {
  //     SmFace * pFace = sFaces[ii] ;
  // 
  //     // sample the Surface along the Face->OuterLoop boundaries
  //     pFace->GetOuterLoopEdges(sEdges) ;
  
      // sample the Surface along the Face->OuterLoop boundaries
      GetOuterLoopEdges(sEdges) ;

      // Dense boundary Edge sampling
      for(ii=0;ii<sEdges.GetSize();ii++)
        {
          SmEdge    * pEdge  = sEdges[ii] ;
          SmCurve   * pCurve = pEdge->GetCurve() ;
          SmExtent1d  sIvl   = pEdge->GetInterval() ;

          for(jj=0;jj<=lSmpCnt_Crv;jj++)
            {
              pCurve->EvaluatePoint(sIvl.Evaluate( (double)jj/(double)lSmpCnt_Crv ), sCrvPt) ;
              SmStatus sRtn = pSurface->DropPoint(sCrvPt,
                                                  sUVDomain,
                                                  sUVLast.IsInitialized()? &sUVLast : NULL,
                                                  bSuccess,
                                                  sUV,
                                                  dGap,
                                                  bIsMulti,
                                                  SM_SO_MINIMIZE) ;
              // skip problem drops
              if(sRtn != SM_SUCCESS)
                { continue ; }

              // save last UV
              sUVLast = sUV ;

              // skip big drop samples
              if(dGap > sXSectTol3d)
                { continue ; }

              // Get the Surface sample Normal
              pSurface->Evaluate1stDerivatives(sUV, TRUE, TRUE, sPt, sDu, sDv) ;

              // simple norm
              SmVector3d sNorm = sDu * sDv ;
              sDu.AngleBetween(sDv, dAngRad) ;

              // skip dependent samples (sDu is zero, sDV is zero, or sNorm is Zero)
              if(   sNorm.LengthSquared() <= SmTol::GetScaledZeroSq(sNorm)
                 || sDu.IsParallelTo(sDv, SM_ANG_TOL_DEG) )
                { continue ; }

              // accumulate Crv Pts - Surface Normal samples
              sPoints.Add(sCrvPt) ;
              sNormals.Add(sNorm) ;

            } // end iter every sample point on this Edge
        } // end iter every Edge
// Remove Composites
//  } // end iter every Face in this composite

  // Sample the Surface along a series of IsoParameter Lines - discard any Dependent Samples
  for(ii=0;ii<=lSmpCnt_U;ii++)
    {
      double dU = sUVDomain.EvaluateU( (double)ii / (double)(lSmpCnt_U) ) ;
      for(jj=0;jj<=lSmpCnt_V;jj++)
        {
          sUV.Set(dU, sUVDomain.EvaluateV( (double)jj / (double)(lSmpCnt_V) )) ;

          // Surface 1st derivatives
          pSurface->Evaluate1stDerivatives(sUV, TRUE, TRUE, sPt, sDu, sDv) ;

          // simple norm
          SmVector3d sNorm = sDu * sDv ;
          sDu.AngleBetween(sDv, dAngRad) ;

          // skip dependent samples (sDu is zero, sDV is zero, or sNorm is Zero)
          if(   sNorm.LengthSquared() <= SmTol::GetScaledZeroSq(sNorm)
             || sDu.IsParallelTo(sDv, SM_ANG_TOL_DEG))
            { continue ; }

          // skip samples not in this face
          SmPointClassification sPointClassification(sZoneTol3d, GetContext()) ;   // should be UVPointZoneTol3d

          // gwc note: this may have to change for composite Faces.  We want to keep all sample points within
          //         any of a CFace->Children faces.
          PointClassify(sUV, sZoneTol3d, FALSE, TRUE, sPointClassification) ;
          if(sPointClassification.GetPointClass() != SM_PC_FACE) // not using pts that classify to edges or vertices
            { continue ; }

          // accumulate samples
          sPoints.Add(sPt) ;
          sNormals.Add(sNorm) ;

        } // end iter jj, every V sample point

    } // end iter ii, every U sample point

  // Arrive here after gathering Sample points and normals - next use NLib to build a surface
#ifdef SM_DEBUG_CODE
SmBoolean bDebugMe = FALSE ;
  if(bDebugMe) // Draw current Surface and sample points
    {
      ULONG di ;
      SmBrep * pBrep = GetBrep() ;
      SM_PTR_ARRAY(dbEdges, SmEdge, 16) ; 
      this->GetEdges(dbEdges) ; 
      SM_ASSERT(sPoints.GetSize() == sNormals.GetSize()) ;
      SM_DUMP_AND_ASSERT_VALID(this) ;
      for(di=0;di<dbEdges.GetSize();di++)
        { SM_DUMP_AND_ASSERT_VALID(dbEdges[di]) ; }

      smgfx_Erase() ;
      smgfx_SetLook( 1, 2, 0, 0, 1 ); if(pBrep) { pBrep->Draw( TRUE ); sm_GraphicsLoop(); }
      smgfx_SetLook( 1, 2, 0, 1, 1 ); if(pSurface) { pSurface->DrawUV(); sm_GraphicsLoop(); }
      smgfx_SetLook( 2, 4, 0, 1, 1 ); if(pSurface) { pSurface->DrawParams(); sm_GraphicsLoop(); }
      smgfx_SetLook( 2, 4, 0, 1, 1 ); if(pSurface) { pSurface->DrawVectorField( sUVDomain, 8, 9, SM_DM_UNIT_NORMAL ); sm_GraphicsLoop(); }
      smgfx_SetLook(1,2, 0,0,0) ; this->Draw() ; sm_GraphicsLoop() ;
      smgfx_SetLook(1,2, 0,0,0) ; this->DrawUV() ; sm_GraphicsLoop() ;
      smgfx_SetLook(1,3, 1,0,0) ; for(di=0;di<sPoints.GetSize();di++) { sPoints[di].Draw() ; sNormals[di].Draw(&sPoints[di]) ;
                                                                        if(di%20 == 0) { sm_GraphicsLoop() ; }
                                                                      }
      sm_GraphicsLoop() ;
    }
#endif // SM_DEBUG_CODE

  // Build a new surface
  SmBSplineSurface::ApproximateRandomPointsNormals(*cpContext,           // in : new object context
                                                    sPoints,             // in : sample points
                                                    sNormals,            // in : associated surface normals
                                                    lMaxUCtrlPnts,       // in : output control point count U
                                                    lMaxVCtrlPnts,       // in : output control point count V
                                                    lUDegree,            // in : output degree U
                                                    lVDegree,            // in : output degree V
                                                    pNewSurf,            // out: approximating surface
                                                    pOptProjectionPlane, // in : Opt projection plane, NULL to ignore
                                                                         //      default:[NULL]
                                                    sApproxTol3d) ;      // in : Max distance allowed between approx and points,
                                                                         //      0.0 to ignore, default:[0.0]
  // Check the Surface quality
  SmBoolean bRtn = pNewSurf ? pNewSurf->AssertValid() : FALSE ;

  // when the Surface passes AssertValid - use it
  if(bRtn)
    {
      // set output
      rpNewBSplineSurface = pNewSurf ;

      // when asked, replace the Face->Surface
      if(bReplaceSurf)
        {
          SmBrep *pBrep = GetBrep() ;

          // branch on the existence of pBrep
          if(pBrep) { pBrep->ReplaceSurface(this,     // in : Target Face to get new Surface
                                            pNewSurf, // in : Target Surface to replace current pFace->Surface
                                            FALSE,    // in : TRUE = add OldSurf to this->m_pDeletedSurfaces list
                                                      //      FALSE= delete OldSurf here
                                                      //      UNSURE= don't delete OldSurf, don't add OldSurf to m_pDeletedSurfaces
                                            NULL,     // out: optional list of modified faces, default:[NULL]
                                            FALSE );  // in : TRUE = recreate Trim Curves, default:[TRUE]
                    }
          else      { SetSurface( pNewSurf, TRUE ) ;
                    }
        }
    } // end built a valid surface check

#ifdef SM_DEBUG_CODE
  if(bDebugMe) // Draw New Surface and sample points
    {
      ULONG di ;
      SmBrep * pBrep = GetBrep() ;
      SM_PTR_ARRAY(dbEdges, SmEdge, 16) ; 
      this->GetEdges(dbEdges) ; 
      SM_ASSERT(sPoints.GetSize() == sNormals.GetSize()) ;
      SM_DUMP_AND_ASSERT_VALID(this) ;
      for(di=0;di<dbEdges.GetSize();di++)
        { SM_DUMP_AND_ASSERT_VALID(dbEdges[di]) ; }

      smgfx_Erase() ;
      smgfx_SetLook( 1, 2, 0, 0, 1 ); if(pBrep) { pBrep->Draw( TRUE ); sm_GraphicsLoop(); }
      smgfx_SetLook( 1, 2, 0, 1, 1 ); if(pNewSurf) { pNewSurf->DrawUV(); sm_GraphicsLoop(); }
      smgfx_SetLook( 2, 4, 0, 1, 1 ); if(pNewSurf) { pNewSurf->DrawParams(); sm_GraphicsLoop(); }
      smgfx_SetLook( 2, 4, 0, 1, 1 ); if(pNewSurf) { pSurface->DrawVectorField( pNewSurf->GetNaturalUVDomain(), 8, 9, SM_DM_UNIT_NORMAL ); sm_GraphicsLoop(); }
      smgfx_SetLook(1,2, 0,0,0) ; this->Draw() ; sm_GraphicsLoop() ;
      smgfx_SetLook(1,2, 0,0,0) ; this->DrawUV() ; sm_GraphicsLoop() ;
      smgfx_SetLook(1,3, 1,0,0) ; for(di=0;di<sPoints.GetSize();di++) { sPoints[di].Draw() ; sNormals[di].Draw(&sPoints[di]) ;
                                                                        if(di%20 == 0) { sm_GraphicsLoop() ; }
                                                                      }
      sm_GraphicsLoop() ;
    }
#endif // SM_DEBUG_CODE

  // all done
  return(bRtn ? SM_SUCCESS : SM_ERR) ;

} // end SmFace::ApproximateSurface

/**************************************************************************//**
PURPOSE: Calculate the normal axis aligned bounding box of the Face.

NOTES: bTight == FALSE, return the Face->Surface->BBox()
       bTight == TRUE,  pass the call to pFace->CalculateTightBoundingBox(),
                        an expensive BBox computation that includes finding all the
                        Face->Surface->GlobalPointSolve(SM_SO_3D_SIGNED_DIRECTED_MAXIMIZE, m_vUVDomain, SM_SW_ALL)
                        solutions for +/- X,Y,and Z directions that classify within the
                        Face's trim boundaries.

  bTight == TRUE is very expensive, it requires
  6 SM_SR_ALL global surface and at least 6 PointClassify calls per face.

  BoundingBoxes are intended to be a cheap and dirty method to help other algorithms to
  run faster by culling geometry that is far from an area of interest.
  That goal is achieved with the CalculateBoundingBox() algorithm which
  often returns a BoundingBox larger than necessary. Typically, calculating a
  tight bounding box is more expensive than the algorithm being helped.

  So, either attempt to write algorithms that work with the often oversized
  results from CalculateBoundingBox, i.e. don't write algorithms that depend on
  the true minimal size of a bounding box.  Or only call CalculateTightBoundingBox
  once for each geometry object and save and reuse the reuslts many times.
*******************************************************************************/
SmStatus SmFace::CalculateBoundingBox
(
  SmExtent3d & rFaceBBox, // out: bounding box as large or larger than this SmFace 
  SmBoolean    bTight     // in : TRUE = compute minimal box (expensive) 
                          //      FALSE= compute any box larger than this Face (cheaper) 
) const
{
  // when asked - call expensive TightBoundingBox
  if( bTight )
    {
      return( CalculateTightBoundingBox( rFaceBBox ) );
    }

  SmExtent3d sFaceBBox;

  SmSurface *pSurface = GetSurface();
  ULONG      lUDeg    = pSurface->GetDegree(SM_SP_U);
  ULONG      lVDeg    = pSurface->GetDegree(SM_SP_V);

  // If one of the directions of the surface is linear
  // we can compute the bounding box using the edges and
  // vertices.
  if (lUDeg == 1 || lVDeg == 1)
  {
      {
    ULONG ii;
    SmVertex* sVData[256];
    SmTArray<SmVertex*> sVertices(256, sVData);
    GetVertices(sVertices);
    for (ii = 0; ii < sVertices.GetSize(); ii++)
    {
        SmVertex* pV = sVertices[ii];
        SM_ASSERT(pV != NULL); // RCLxx This hides a problem that shows up elsewhere
        if (pV == NULL)
            continue; // RCLxx
        SmExtent3d sVBBox(pV->GetPoint());
        sVBBox.ExpandAbsolute(pV->GetTolerance());
        sFaceBBox.Union(sVBBox, sFaceBBox);
    } // end loop on Vertices

    // Now load the Edge Tree
    SmEdge* sEData[256];
    SmTArray<SmEdge*> sEdges(256, sEData);
    GetEdges(sEdges);
    for (ii = 0; ii < sEdges.GetSize(); ii++)
    {
        SmEdge* pE = sEdges[ii];
        SmExtent3d sEBBox;
        SmCurve* pCurve = pE->GetCurve();
        if (pCurve != NULL)
        {
            SER(pCurve->CalculateBoundingBox(pE->GetInterval(), &sEBBox));
            sEBBox.ExpandAbsolute(pE->GetTolerance());
#    ifdef SM_DEBUG_CODE
            SmBoolean bDebugMe = FALSE;
            if (bDebugMe)
            {
                pE->GetCurve()->Dump();
                pE->GetInterval().Dump();
                smgfx_Erase();
                smgfx_SetLook(1, 1, 1, 0, 0);
                pE->Draw();
                sm_GraphicsLoop();
                smgfx_SetLook(1, 1, 0, 0, 0);
                Draw();
                sm_GraphicsLoop();
                sm_GraphicsLoop();
            }
#    endif // SM_DEBUG_CODE
            sFaceBBox.Union(sEBBox, sFaceBBox);
        }
    } // end loop on Edges
} // end linear direction in surface check

  }
  else // Get the bounding box of the surface
  {
      SER(pSurface->CalculateBoundingBox(GetUVDomain(),&sFaceBBox));
  }

  // Set output and return
  rFaceBBox = sFaceBBox;

  return SM_SUCCESS;

} // end SmFace::CalculateBoundingBox

/*******************************************************************//**
PURPOSE: Calculate a more precise normal axis aligned bounding box of the Face.

NOTES: The returned BBox is the union of
  1. all Face vertices
  2. All Face->Edge->CalculateTightBoundingBoxes
  3. All Face->Surface->GlobalPointSolve(SM_SO_3D_SIGNED_DIRECTED_MAXIMIZE, m_vUVDomain, SM_SW_ALL)
                 solutions for +/- X,Y,and Z directions that classify within the
                 Face's trim boundaries.

  CalculateTightBoundingBox() is very expensive, it requires
  6 SM_SR_ALL global surface and at least 6 PointClassify calls per face.

  BoundingBoxes are intended to be a cheap and dirty method to help other algorithms to
  run faster by culling geometry that is far from an area of interest.
  That goal is achieved with the CalculateBoundingBox() algorithm which
  often returns a BoundingBox larger than necessary. Typically, calculating a
  tight bounding box is more expensive than the algorithm being helped.

  So, either attempt to write algorithms that work with the often oversized
  results from CalculateBoundingBox, i.e. don't write algorithms that depend on
  the true minimal size of a bounding box.  Or only call CalculateTightBoundingBox
  once for each geometry object and save and reuse the reuslts many times.
***********************************************************************/
SmStatus SmFace::CalculateTightBoundingBox( SmExtent3d & rFaceBBox ) const
{
  SmExtent3d sFaceBBox;

  SmSurface * pSurface       = GetSurface();
  SmZoneTol3d sFaceZoneTol3d = SmTol::GetZoneTol3d(this) ;

  // Method: get the bounding box of the Vertices.
  // Then get the tight box of each Edge and union it in.
  // Then get our surface's loose BBox (cheap).
  // If it's not entirely contained in the box so far,
  // calculate its tight box and union it in.

  // Vertices:
  SmVertex * sVData[256];
  SmTArray<SmVertex*> sVertices(256,sVData);
  GetVertices( sVertices );
  for ( ULONG i=0; i<sVertices.GetSize(); i++ )
    {
      SmVertex *pV = sVertices[i];
      SM_ASSERT(pV !=NULL);        // RCLxx This hides a problem that shows up elsewhere
      if (pV == NULL) continue;    // RCLxx

      sFaceBBox.AddPoint3d( pV->GetPoint() );
    } // end loop on Vertices

  // Edges:
  SmEdge * sEData[256];
  SmTArray<SmEdge*> sEdges(256,sEData);
  GetEdges( sEdges );
  ULONG j;
  for ( j=0; j<sEdges.GetSize(); j++ )
    {
      SmEdge *pE = sEdges[j];
      SmExtent3d sEBBox;

#ifdef SM_DEBUG_CODE
SmBoolean bDebugMe=FALSE;
      if (bDebugMe)
        {
          pE->GetCurve()->Dump();
          pE->GetInterval().Dump();
          smgfx_Erase();
          smgfx_SetLook(1,1, 0,0,0);     Draw(); sm_GraphicsLoop();
          smgfx_SetLook(3,1, 1,0,0); pE->Draw(); sm_GraphicsLoop();
          sm_GraphicsLoop();
        }
#endif // SM_DEBUG_CODE
      // Get this Edge's tight box
      SER( pE->CalculateTightBoundingBox( &sEBBox) );

      sFaceBBox.Union( sEBBox, sFaceBBox );
    } // end loop on Edges

  // Set output to what we have so far.
  rFaceBBox = sFaceBBox;

  // Now the surface.
  // If it's a plane, then we're done.
  if ( pSurface->IsPlanar( SM_EFF_ZERO ) )
    { return SM_SUCCESS; }

  SmExtent3d sSurfBBox;

  // First check the approximate box.
  SER( pSurface->CalculateBoundingBox( GetUVDomain(), &sSurfBBox ));
  if ( sSurfBBox.IsContainedBy( sFaceBBox ) )
    { return SM_SUCCESS; }

  // Unfortunately, we can't just call the surface method with our domain,
  // that box could well be larger than that of the Face.
  // So we have to reproduce the Surface method here,
  // and check each solution for being inside the Face.
  //
  //  SER( pSurface->CalculateTightBoundingBox( GetUVDomain(), &sSurfBBox ));
  //  sFaceBBox.Union( sSurfBBox, sFaceBBox );

  // Begin copy of Surface::CalculateTightBoundingBox():
  // NOTE: if you modify this, also look at SmSurface::CalculateTightBoundingBox().

  SmSolutionArray sSolutions;
  SmSurfaceEval sEval( pSurface );
  SmPointClassification sPtClass(sFaceZoneTol3d, GetContext()) ;  // should be sEval UVPointZoneTol3d
  sSurfBBox.Init();

  SmVector3d sDirVec( 1, 0, 0 );  // +/- x

  ULONG idx;
  for ( idx = 0; idx < 3; idx++ )
    {
      if ( idx == 1 ) sDirVec.Set( 0, 1, 0 );  // +/- y
      if ( idx == 2 ) sDirVec.Set( 0, 0, 1 );  // +/- z

      // Positive direction:
      pSurface->GlobalPointSolve(m_vUVDomain,
                                 SM_SO_3D_SIGNED_DIRECTED_MAXIMIZE,
                                 sDirVec,
                                 SM_EFF_ZERO_SQRT,
                                 NULL,
                                 SM_SR_ALL,
                                 sSolutions) ;

      for ( j = 0; j < sSolutions.GetSize(); j++ )
        {
          sEval.SetUV( sSolutions[j].m_vStart[0], sSolutions[j].m_vStart[1] );
          PointClassify( sEval.GetUV(), sFaceZoneTol3d, FALSE, TRUE, sPtClass );
          if ( sPtClass.GetPointClass() != SM_PC_UNKNOWN )
            { sSurfBBox.AddPoint3d( sEval.Pos() ); }
        }

      // Negative direction:
      sDirVec = -sDirVec;

      pSurface->GlobalPointSolve(m_vUVDomain, 
                                 SM_SO_3D_SIGNED_DIRECTED_MAXIMIZE,
                                 sDirVec,
                                 SM_EFF_ZERO_SQRT,
                                 NULL,
                                 SM_SR_ALL,
                                 sSolutions);

      for ( j = 0; j < sSolutions.GetSize(); j++ )
        {
          sEval.SetUV( sSolutions[j].m_vStart[0], sSolutions[j].m_vStart[1] );
          PointClassify( sEval.GetUV(), sFaceZoneTol3d, FALSE, TRUE, sPtClass );
          if ( sPtClass.GetPointClass() != SM_PC_UNKNOWN )
            { sSurfBBox.AddPoint3d( sEval.Pos() ); }
        }
    } // end for on x, y, z directions

    sFaceBBox.Union( sSurfBBox, sFaceBBox );

  // End copy of Surface::CalculateTightBoundingBox():

  // Set output and return
  rFaceBBox = sFaceBBox;

  return SM_SUCCESS;

} // end SmFace::CalculateTightBoundingBox

/****************************************************************
PURPOSE: Classify a uv line between two given points against a Face.

NOTES:
****************************************************************/
static SmStatus sm_FaceClassifyUVLine
(
  const SmFace * pFace,                        // in : target face 
  const SmPoint2d & sUVStart,                  // in : Start Param 
  const SmPoint2d & sUVEnd,                    // in : End Param 
  SmZoneTol3d sSrcZoneTol3d,                   // in : obj ZoneTol3d assoc with UVLine, if none, use:SmTol::GetZoneTol3d(Brep_Context_Or_NULL) 
  SmCurveClassification & rCurveClassification // out: inside/on UVCurve segments from specified UVStart/UVEnd points 
                                               //      all curves in this array must be deleted by the caller 
)
{
  // init output
  rCurveClassification.ReSet() ;

  // build UVLine
  SmPoint3d sStart(sUVStart.x, sUVStart.y, 0.0) ;
  SmPoint3d sEnd  (sUVEnd.x,   sUVEnd.y,   0.0) ;
  SmLine *pNewUVLine = NULL ;

  SmLine::CreateLineSegment(*pFace->GetContext(), 2, sStart, sEnd, pNewUVLine) ;
  NER( pNewUVLine );

#ifdef SM_DEBUG_CODE
SmBoolean bDebugMe=FALSE;
  if ( bDebugMe )
  {
      if ( FALSE ) {
          smgfx_Erase();
          smgfx_SetLook( 1,2, 0,1,1 ); pFace->GetSurface()->DrawUV(3,3); sm_GraphicsLoop();
          smgfx_SetLook( 4,6, 0,0,0 ); pFace->Draw(); sm_GraphicsLoop();
          sm_GraphicsLoop();
      }
      SmCrvOnSurf *pCOS = new( pFace->GetContext() ) SmCrvOnSurf( *pNewUVLine, *(pFace->GetSurface()) );
      smgfx_SetLook( 2,4, 1,0,0 ); pCOS->Draw(); sm_GraphicsLoop();
      sm_GraphicsLoop();
  }
#endif // SM_DEBUG_CODE

  // Load the new curve into the CurveClassification so that curve gets deleted by rCurveClassification
  // Also need to pass Domain and Tolerance. [B327]
  SmExtent1d sDomain = pNewUVLine->GetNaturalInterval();

  // Figure a tolerance for the CurveClassification:
  // Must be a 2d tolerance because the curve is a 2d curve.
  SmVector2d sUVScale = pFace->GetSurface()->ApproxDerivativeLengths( pFace->GetUVDomain() );
  double dUVScale = sUVScale.Length();
  if ( dUVScale < sSrcZoneTol3d / 1000 )
    { dUVScale = sSrcZoneTol3d / 1000; }

  // double dTolUV = sSrcZoneTol3d / dUVScale;

  // Note: ReSet() tells the CC that pNewUVLine is owned, so it will be deleted.
  rCurveClassification.ReSet( pNewUVLine, &sDomain, pNewUVLine, sSrcZoneTol3d, 0, NULL, TRUE, TRUE, pFace->GetSurface()) ;

  // ask the face to classify the curve
  SER(pFace->CurveOnClassify(TRUE,rCurveClassification));

  return SM_SUCCESS;

} // end sm_FaceClassifyUVLine

/*******************************************************************//**
PURPOSE: Generates a point known to be on the face and inside the face boundaries.

NOTES: This is useful for generating graphic points for faces
different than their boundary and vertex points.
***********************************************************************/
SmStatus SmFace::CalculateAnInternalPoint( SmPoint3d &rPointInFace ) const
{
  // init output
  rPointInFace.Set(0,0,0) ;

  // locals
  ULONG ii, jj, kk;
  SmSurface           * pSurface      = GetSurface() ;
  //SmBSplineSurface    * pBSS          = SM_CAST_PTR(SmBSplineSurface,GetSurface());
  SmExtent2d            sUVDomain     = m_vUVDomain ;
  double                dUMin         = sUVDomain.GetUMin() ;
  double                dUMax         = sUVDomain.GetUMax() ;
  double                dVMin         = sUVDomain.GetVMin() ;
  double                dVMax         = sUVDomain.GetVMax() ;
  SmZoneTol3d           sSrcZoneTol3d = SmTol::GetZoneTol3d(this);
  double                dU, dV ;
  SmPoint2d             sStart, sEnd, sUVPoint ;
  SmCurveClassification sCurveClassification ;

  // no work - no surface
  if(pSurface == NULL)
    { return( SM_ERR ) ; }

  // no work - Bspline surface with no owner - probably
  // been set to NULL to prevent building the TrimSrfCache before the face is ready.
  if(pSurface->GetOwner() == NULL)
    { return( SM_ERR ) ; }

  // first for constant U then V isoparameter lines
  for(ii=0;ii<2;ii++)
    {
      // for a family of U or V isoparameter lines - find internal points by classifying UVLines
      for(jj=0;jj<20;jj++)
        {
          double dParam = (double)jj/21.0 ;

          if(ii==0) // constant V
            {
              dV = (1.0 - dParam) * dVMin + (dParam) * dVMax ;
              sStart.Set(dUMin, dV) ;
              sEnd.Set  (dUMax, dV) ;
            }
          else // constant U
            {
              dU = (1.0 - dParam) * dUMin + (dParam) * dUMax ;
              sStart.Set(dU, dVMin) ;
              sEnd.Set  (dU, dVMax) ;
            }

          // classify the target UVLine
          sm_FaceClassifyUVLine(this, sStart, sEnd, sSrcZoneTol3d, sCurveClassification);

          // when intervals were found in the face
          for ( kk=0; kk<sCurveClassification.GetSize(); kk++ )
            {
              // Check the midPoint of this interval.
              SmCurveInterval & rCurveInterval = sCurveClassification[ kk ];
              if ( rCurveInterval.m_vMid.GetPointClass() == SM_PC_FACE )
                {
                  // Found an interior point.
                  const SmCurve *pUVCrv = sCurveClassification.GetCurve(); // This is a uv-space curve.
                  double dCurveParameter = rCurveInterval.m_vInterval.Evaluate(.45) ;

                  // if (ii==0) { sUVPoint.Set(dCurveParameter, dV) ; }
                  // else       { sUVPoint.Set(dU, dCurveParameter) ; }

                  SmPoint3d sUV_Vec3d;
                  if ( pUVCrv->EvaluatePoint( dCurveParameter, sUV_Vec3d ) != SM_SUCCESS )
                    { continue; }

                  sUVPoint.Set( sUV_Vec3d.x, sUV_Vec3d.y );
                  if ( pSurface->EvaluatePoint( sUVPoint, rPointInFace ) != SM_SUCCESS )
                    { continue; }

                  // all done
                  return(SM_SUCCESS) ;
                }
            } // end iter every found curve interval
        } // end iter every constant curve
    } // end iter V or U Curve

  // arrive here when no curve classify to face
  return(SM_ERR) ;

} // end SmFace::CalculateAnInternalPoint

/*******************************************************************//**
PURPOSE: Calculate UV Domain of the face from the trim curves bounding box and
 optionally find the max Loop->Edgeuse_to_Edgeuse end_to_end gap in 
 UV and 3d spaces.

NOTES: If SmFace::CreateUVTrimCurves() fails, the outputs are
   set to rNewFaceDomain = this->GetUVDomain(), pOptMaxUVLoopGap = 0.0,
   and pOptMax3dLoopGap = 0.0, else the NewFaceDomain is set equal
   to  rNewFaceDoain = Union(Every Loop, Every Edgeuse BBox)
       pOptMax3dLoopGap = Max( Every Loop, Every Edgeuse_to_Edgeuse End_to_End 3d Gap)
       pOptMaxUVLoopGap = Max( Every Loop, Every Edgeuse_to_Edgeuse End_to_End UV Gap)

   The returned domain will be no larger than current face domain.
   This will prevent us from creating a box from curves whose control
   vertices are off the domain but whose curves are good.  If you think
   the domain might grow then you need to set the face domain to that of
   the surface and then shrink from there.
***********************************************************************/
SmStatus SmFace::CalculateUVDomainFromUVTrimCurves
 (SmExtent2d & rNewFaceDomain,      // out: UV BoundingBox for all UVTrimCurve Control Point Positions
  SmBoolean    bLimitDomain,        // in : TRUE= do not return a domain larger than the surface's domain Default:[TRUE]
  double     * pOptMaxUVLoopGap,    // out: Max 2D Loop->EdgeuseEnd_to_EdgeuseEnd Gap, NULL to ignore. Default:[NULL]
  double     * pOpt2ndMaxUVLoopGap) // out: 2nd largest UVLoopGap (for MissingSeamFaces where MaxUVLoopGap can be as 
                                    //    : large as the surface domain but the 2nd largest is expected to be a good  
                                    //    : size scale for tolerances.) NULL to ignore, Default:[NULL]
 const
{
  // locals
  double dTmp;
  SM_PTR_ARRAY(sLoopuses,SmLoopuse,32);
  SM_PTR_ARRAY(sEdgeuses,SmEdgeuse,64);
  this->GetUpwardLoopuses(sLoopuses);

  // Init output 
  rNewFaceDomain = this->GetUVDomain();
  if(pOptMaxUVLoopGap)    { *pOptMaxUVLoopGap    = 0.0 ; }
  if(pOpt2ndMaxUVLoopGap) { *pOpt2ndMaxUVLoopGap = 0.0 ; }
  
  // Check State - no Face->Surface
  if ( m_pSurface == NULL )
    { return SM_SUCCESS ; }

  // locals
  SmExtent2d       sThisDomain = rNewFaceDomain ;
  SmExtent2d       sSurfDomain = m_pSurface->GetNaturalUVDomain();
  SmPoint2d        sLastEndUV, sThisEndUV ;

  // limit ThisDomain to XSect(Face->UVDomain, Face->Surface->UVDomain) (a fix for a common problem)
  sThisDomain.Intersect( sSurfDomain, rNewFaceDomain );

  // place a UVTrimCurve on each Face->Edgeuse
  SmStatus eStat = CreateUVTrimCurves(
                       FALSE,             // in : TRUE = adjust Edge and Vertex tolerances to include measured gaps
                       NULL,              // in : optional array of UVTrimCurves to assign to Face->Edgeuses
                       NULL,              // in : associated orientations. If cpOptUVCurves notNULL, then cpOptOrientations must be notNULL.
                       dTmp,dTmp,dTmp,
                       dTmp,dTmp,dTmp);

  if ( eStat != SM_SUCCESS )
    { return SM_SUCCESS; }  // Return the default from above.

  // old place a UVTrimCurve on each Face->Edgeuse
  // // guarantee every face->Edgeuse has a UVTrimCurve
  // this->GetUpwardLoopuses(sLoopuses);
  // {
  //   // for every upward loopuse
  //   for (ULONG ii=0; ii<sLoopuses.GetSize(); ii++)
  //     {
  //       SmLoopuse *pLU = (SmLoopuse*)sLoopuses[ii];
  //       pLU->GetEdgeuses(sEdgeuses);
  // 
  //       // for every edgeuse
  //       for (ULONG j=0; j<sEdgeuses.GetSize(); j++)
  //       {
  //         SmEdgeuse * pEU = (SmEdgeuse*)sEdgeuses[j];
  //         SmBSplineCurve * pUVCurve = NULL ;
  //         SER(pEU->GetOrCreateUVTrimCurve(pUVCurve)) ;
  //       } // end iter every edgeuse
  //     } // end iter every loopuse
  // }

  // Build union of all face->Edgeuse UVBoundingBoxes
  // Save Loop Edgeuse_to_Edgeuse End_to_End gaps
  SmExtent2d sFaceDomain;
  SmBoolean bBoxSet = FALSE;
  {
    // for every upward loopuse
    for (ULONG ii=0; ii<sLoopuses.GetSize(); ii++)
      {
        SmLoopuse *pLU = (SmLoopuse*)sLoopuses[ii];
        pLU->GetEdgeuses(sEdgeuses);

        double dThisMaxUVLoopGap    = 0.0 ; 
        double dThis2ndMaxUVLoopGap = 0.0 ; 

        // for every edgeuse
        for (ULONG jj=0; jj<sEdgeuses.GetSize(); jj++)
          {
            SmEdgeuse      * pEU      = (SmEdgeuse*)sEdgeuses[jj];
            SmBSplineCurve * pUVCurve = pEU->GetUVTrimCurve() ;
            SmExtent1d       sUVIvl   = pUVCurve->GetNaturalInterval() ;

            // get Edgeuse UVBoundingBox (have to use a SmExtend3d)
            SmExtent3d sCrvBox;
            SER(pUVCurve->CalculateBoundingBox(sUVIvl,&sCrvBox));

            // Get Max Edgeuse_to_Edgeuse 2d UVSpace gap
            if(pOptMaxUVLoopGap)
              {
                double dThisUVLoopGap = pEU->GetStartPointUVLoopGap() ;
                if(dThisMaxUVLoopGap < dThisUVLoopGap)
                  { 
                    dThis2ndMaxUVLoopGap = dThisMaxUVLoopGap ; 
                    dThisMaxUVLoopGap    = dThisUVLoopGap ; 
                  }
              }

            // convert 3d Extent to 2d
            SmExtent2d sUVCrvBox(sCrvBox);

            // get union of Edgeuse UVTrimCurve BoundingBoxes
            if ( ii == 0 && jj == 0 )
                sFaceDomain = sUVCrvBox;
            else
                sFaceDomain.Union( sUVCrvBox, sFaceDomain );

            bBoxSet = TRUE;
          } // end iter every edgeuse[jj]

      if(pOptMaxUVLoopGap && *pOptMaxUVLoopGap < dThisMaxUVLoopGap) 
        { *pOptMaxUVLoopGap = dThisMaxUVLoopGap ; } 
      if(pOpt2ndMaxUVLoopGap && *pOpt2ndMaxUVLoopGap < dThis2ndMaxUVLoopGap) 
        { *pOpt2ndMaxUVLoopGap = dThis2ndMaxUVLoopGap ; }

      } // end iter every loopuse[ii]
  } // end build union of all face->Edgeuse UVBoundingBoxes

  // If we are limiting the size of the return domain,
  if ( bLimitDomain )
    {
      // Don't return a UVTrimCurve Bounding Box larger than the surface
      // natural Interval.  The bounding box is constructed from the
      // control points of the UVTrimCurves which may lie outside of the
      // surface's natural interval.
      // Use the surface's domain if available, not the Face's current domain.  [B306]

      if ( bBoxSet )
        {
          SER( sFaceDomain.Intersect( sSurfDomain, sFaceDomain ));
        }
      else
        {
          sFaceDomain = sSurfDomain;
        }
    }

  // all done - set output and return
  rNewFaceDomain = sFaceDomain;
  return SM_SUCCESS;

} // end SmFace::CalculateUVDomainFromUVTrimCurves

/*******************************************************************//**
PURPOSE: Calculate UV Domain of the face from the trim curves bounding box and
 optionally find the max Loop->Edgeuse_to_Edgeuse end_to_end gap in 
 UV and 3d spaces.

NOTES: outputs set to
         rNewFaceDomain   = Union(EveryLoop: EveryEdgeuse: BBox) (for BSPlines this is the CtrlPt BBox)
         pOptMax3dLoopGap = Max(EveryLoop: EveryEdgeuse_to_Edgeuse: End_to_End Gap3d)
         pOptMaxUVLoopGap = Max(EveryLoop: EveryEdgeuse_to_Edgeuse: End_to_End GapUV)

   This method can only shrink the FaceDomain because  
   The returned rNewFaceDomain is trimmed to be no larger than current FaceDomain to 
   prevent creating NewFaceDomains bigger than the Face->Surface's NaturalDomain because
   of valid UVTrimCurves whose CtrlPts happen to lie beyond the NaturalDomain boundaries.
   
   To use this function to grow rNewFaceDomain as needed, 
     1st set FaceDomain = Face->Surface->NaturalDomain and 
     then call this method to shrink from there.
***********************************************************************/
SmStatus SmFace::CalculateMaxLoopUVGap
(double  & rMaxUVLoopGap,       // out: Max 2D Loop->EdgeuseEnd_to_EdgeuseEnd Gap, NULL to ignore. Default:[NULL]
 double  * pOpt2ndMaxUVLoopGap  // out: 2nd largest UVLoopGap (for MissingSeamFaces where MaxUVLoopGap can be as 
                                //    : large as the surface domain but the 2nd largest is expected to be a good  
                                //    : size scale for tolerances.) NULL to ignore, Default:[NULL]
) const
{
  // locals
  SM_PTR_ARRAY(sLoopuses,SmLoopuse,32);
  SM_PTR_ARRAY(sEdgeuses,SmEdgeuse,64);
  this->GetUpwardLoopuses(sLoopuses);

  // Init output 
  rMaxUVLoopGap = 0.0 ;
  if(pOpt2ndMaxUVLoopGap) { *pOpt2ndMaxUVLoopGap = 0.0 ; }
  
  // no longer needed - GetStartPointUVLoopGap() extended to work when UVTrimCrvs are missing
  //   // Ensure a UVTrimCurve on each Face->Edgeuse
  //   SmStatus eStat = CreateUVTrimCurves(
  //                      FALSE,             // in : TRUE = adjust Edge and Vertex tolerances to include measured gaps
  //                      NULL,              // in : optional array of UVTrimCurves to assign to Face->Edgeuses
  //                      NULL,              // in : associated orientations. If cpOptUVCurves notNULL, then cpOptOrientations must be notNULL.
  //                      dTmp,dTmp,dTmp,
  //                      dTmp,dTmp,dTmp);
  //   
  //   if ( eStat != SM_SUCCESS )
  //     { return SM_SUCCESS; }  // Return the default from above.

  // Save Loop Edgeuse_to_Edgeuse End_to_End max gap
  for (ULONG ii=0; ii<sLoopuses.GetSize(); ii++)
    {
      SmLoopuse *pLU = (SmLoopuse*)sLoopuses[ii];
      pLU->GetEdgeuses(sEdgeuses);
      double dThisMaxUVLoopGap    = 0.0 ; 
      double dThis2ndMaxUVLoopGap = 0.0 ; 

      // for every edgeuse
      for (ULONG jj=0; jj<sEdgeuses.GetSize(); jj++)
        {
          SmEdgeuse      * pEU      = (SmEdgeuse*)sEdgeuses[jj];

          // Get Max Edgeuse_to_Edgeuse 2d UVSpace gap - no longer builds missing UVTrimCurves
          double dThisUVLoopGap = pEU->GetStartPointUVLoopGap() ;
          if(dThisMaxUVLoopGap < dThisUVLoopGap)
            { dThis2ndMaxUVLoopGap = dThisMaxUVLoopGap ;  
              dThisMaxUVLoopGap    = dThisUVLoopGap ; 
            }

        } // end iter every edgeuse[jj] 
      
      // update outputs
      if(rMaxUVLoopGap < dThisMaxUVLoopGap) 
        { rMaxUVLoopGap = dThisMaxUVLoopGap ; } 
      if(pOpt2ndMaxUVLoopGap && *pOpt2ndMaxUVLoopGap < dThis2ndMaxUVLoopGap) 
        { *pOpt2ndMaxUVLoopGap = dThis2ndMaxUVLoopGap ; }

    } // end iter every loopuse[ii]

  // all done
  return SM_SUCCESS;

} // end SmFace::CalculateMaxLoopUVGap

/*******************************************************************//**
PURPOSE: Static helper for ComputeLoopOrientation(): determine whether
   two Edgeuses are connected, in uv parameter space.

NOTES:
   If bSingularityOK is True, then curves that meet at the same singularity
   will be considered connected.

   If a Loop is not closed in uv space, then use the 3d algorithm,
   which does not use uv trim curves.
***********************************************************************/
static SmBoolean sm_AreConnected
(
  const SmEdgeuse * pEU1,                    // in : check pEU1->EndPt Position
  const SmEdgeuse * pEU2,                    // in : check pEU2->StartPt Position
  SmBoolean bSingularityOK = TRUE,           // in : TRUE = if UVGap > UVtol, Rtn TRUE if UVGap is along a Singularity boundary
                                             //      FALSE= if UVGap > UVTol, Always rtn FALSE
  SmBoolean bCrossesMissingSeamOK = FALSE,   // in : TRUE = if UVGap > UVtol, Rtn TRUE if UVGap is accross a missing seam
                                             //      FALSE= if UVGap > UVTol, Always rtn FALSE
  SmBoolean * pOptOnSingularity=NULL,        // out: TRUE=UVGap > UVtol && OnSingularity,FALSE=not, NULL to ignore, default:[NULL]
  SmBoolean * pOptCrossesMissingSeam=NULL    // out: TRUE=UVGap > UVTol && CrossesMissingSeam,FALSE=not, NULL to ignore, default:[NULL]
)
{
  // init output
  if( pOptOnSingularity)        { * pOptOnSingularity      = FALSE ; } 
  if( pOptCrossesMissingSeam  ) { * pOptCrossesMissingSeam = FALSE ; }
  
  // Get end of pEU1 and start of pEU2.
  SmVertexuse *pVU1 = pEU1->GetMate()->GetVertexuse() ; // End of this is start of Mate.
  SmVertexuse *pVU2 = pEU2->GetVertexuse() ;

  SmPoint2d sUV1, sUV2 ;
  pVU1->ComputeUVPoint( sUV1, FALSE ) ; // TRUE  = Use LocalSolve with guesses from UVTrimCurve
  pVU2->ComputeUVPoint( sUV2, FALSE ) ; // FALSE = don't make UVTrimCurve, if missing use GlobalSolve
  double dGapU = smos_Fabs(sUV2.x - sUV1.x) ;
  double dGapV = smos_Fabs(sUV2.y - sUV1.y) ;

  SmSurface * pSurf     = pEU1->GetFace()->GetSurface() ;
  SmZoneTol3d s3DTol    = pVU1->GetVertex()->GetTolerance() ;
  SmTol2d     sUVTol    = SmTol::MapTo2d( s3DTol, sUV1, *pSurf ) ;

  if(sUV1.DistanceBetween( sUV2 ) < sUVTol)
    { return TRUE; }

  // when gaps across singularities are allowed
  if(bSingularityOK )
    {
      SmSurfParamType eDir1 ; // output arg
      SmSurfParamType eDir2 ; // output arg
      SmBoolean bOnSingularity1 = pSurf->IsSingularity( sUV1, eDir1, s3DTol, TRUE ) ;
      SmBoolean bOnSingularity2 = pSurf->IsSingularity( sUV2, eDir2, s3DTol, TRUE ) ;

      // both ends are on a singularity
      if(bOnSingularity1 && bOnSingularity2)
        {
          // set output
          if(pOptOnSingularity) 
            { *pOptOnSingularity = TRUE ; }
        
          // check for a properly oriented singularity at the gap
          if((eDir1 == SM_SP_BOTH) && (eDir2 == SM_SP_BOTH))
            {
              { return TRUE ; }
            }

          else if((eDir1 == SM_SP_U || eDir1 == SM_SP_BOTH) && (eDir2 == SM_SP_U || eDir2 == SM_SP_BOTH))
            {
              if(dGapV < sUVTol)
                { return TRUE ; }
            }

          else if((eDir1 == SM_SP_V || eDir1 == SM_SP_BOTH) && (eDir2 == SM_SP_V || eDir2 == SM_SP_BOTH))
            {
              if(dGapU < sUVTol)
                { return TRUE ; }
            }
        } // end both points on singularity check
    } // end when gaps across singularities are allowed check

  // when gaps across MissingSeams are allowed
  if(bCrossesMissingSeamOK )
    {
      // check for a properly oriented seam gap
      SmExtent2d sUVDomain = pSurf->GetNaturalUVDomain() ;
      SmBoolean  bClosedU  = pSurf->IsClosed(sUVDomain, SM_SP_U, &sUVTol.val) ;
      SmBoolean  bClosedV  = pSurf->IsClosed(sUVDomain, SM_SP_V, &sUVTol.val) ; 
      
      // when surface is closed
      if(bClosedU || bClosedV)
        {
          if(bClosedU && bClosedV)
            {
              if(   ((dGapU < sUVTol) || (smos_Fabs(dGapU - sUVDomain.XLength()) < sUVTol))
                 && ((dGapV < sUVTol) || (smos_Fabs(dGapV - sUVDomain.YLength()) < sUVTol)))
                { if(pOptCrossesMissingSeam) 
                   { *pOptCrossesMissingSeam = TRUE ; }
                  return TRUE ; 
                }
            }
          else if(bClosedU)
            {
              if(   (smos_Fabs(dGapU - sUVDomain.XLength()) < sUVTol)
                 && (dGapV < sUVTol))
                { if(pOptCrossesMissingSeam) 
                   { *pOptCrossesMissingSeam = TRUE ; }
                  return TRUE ; 
                }
            }
          else // bClosedV
            {
              if(   (smos_Fabs(dGapV - sUVDomain.YLength()) < sUVTol)
                 && (dGapU < sUVTol))
                { if(pOptCrossesMissingSeam) 
                   { *pOptCrossesMissingSeam = TRUE ; }
                  return TRUE ; 
                }
            } // end Surf is closed check
        } // end connections crossing missing seams ok check
    } // end when gaps across singularities are allowed check
  // all done
  return FALSE;

}  // end static sm_AreConnected

/*******************************************************************//**
PURPOSE: Compute the orientation of a loop within a face.

NOTES: SM_OT_SAME     = CCW Outer Loop
       SM_OT_OPPOSITE = CW  Inner Loop

   If the given loop has zero area, this will return SM_SUCCESS,
   with reLoopOrient set to SM_OT_UNKNOWN.

   Note: this is true for uv-space computation only:
   if bDo3DLoopComputation = False:
     If the loop contains any seam edges, 
     or indeed any edges that touch a surface boundary,
     then it is presumed to be an outer loop,
     and this will return SM_OT_SAME.
     (Every inner loop must be strictly contained inside an outer loop,
     and no loop can extend outside of the surface's boundaries, so an
     inner loop cannot touch a surface boundary.)
   if bDo3DLoopComputation = True:
     In a well-formed model, any part of a Loop that touches a seam or
     any Face boundary would indicate an outer loop, but that might not be
     the case in the 3d branch.  That is invoked when the uv trim curves
     might not be reliable, e.g., during read-in from a non-SMLib file.
     At any rate, this routine is intended to calculate orientation,
     not to decide inner/outer, so don't do this in the 3d case.  [B522]

   If the loop is a vertex loop, or is not closed,
   then it is presumed to be an inner loop,
   and this will return SM_OT_OPPOSITE.

   bDo3DLoopComputation: Pass this as True to prevent the use of UVTrimCurves
   on Edgeuses.  This will be the case during read-in, for example, when the
   Face/Edge topology might not conform to SMLib requirements, e.g., Edges and
   Faces spanning surface seams.  Note, the 3d version still requires dropping
   points to the surface to get uv values, but does not assume that valid 
   UVTrimCurves exist.

METHOD:
   In the 3d branch, this formerly integrated turning angles at sample points
   around the Loop.  There are two ways that that method can fail.  One can be
   illustrated on a torus.  Moving around the 'top' of the torus, the direction
   will turn, but around the outside or inside, it will not (when measured
   in the tangent plane).  A loop that runs all the way around the outside,
   then 90 degrees up the seam to the top, and all the way back and down the
   seam, the net angle change will be zero.  (360 degrees from the 'top' edge,
   plus four 90-degree corners.)

   Another counterexample is a Loop with a slight overlap: picture a cusp that
   actually overlaps itself just a tiny bit.  At that vertex, the turning angle
   will be close to 360 degrees, in the wrong direction.

   Using the area-integration algorithm avoids all that.  [B522]
***********************************************************************/
SmStatus SmFace::ComputeLoopOrientation
(
  const SmLoop * pLoop,                 // in : target loop
  SmOrientType & reLoopOrient,          // out: SM_OT_SAME     = outerLoop
                                        //      SM_OT_OPPOSITE = InnerLoop
  SmExtent2d   * pUVBounds,             // out: UVBoundingBox of all loop->Edges
                                        //      NULL to ignore. default:[NULL]
  SmBoolean      bDo3DLoopComputation   // in : TRUE  = Walk candidate outerLoops in 3D to classify
                                        //      FALSE = Walk candidate outerLoops in 2D to classify
                                        //      default:[FALSE]
)  const
{
  // check input
  NER(pLoop);

  // init output
  reLoopOrient = SM_OT_UNKNOWN ; 
  if(pUVBounds != NULL) 
    { pUVBounds->Init(); }

  // get Loopuses
  SmLoopuse *pLU1, *pLU2;
  pLoop->GetLoopuses(pLU1,pLU2);

  // First try to compute loop orientation topologically.
  // Shell vertices and non-enclosing loops must be inner loops,
  // and so have opposite orientation.

  // VertexLoops are InnerLoops
  if ( pLU1->IsVertexLoopuse() )
    {
      reLoopOrient = SM_OT_OPPOSITE;
      return SM_SUCCESS;
    } // end Vertexloop check

#ifdef SM_DEBUG_CODE
SmBoolean bDebugMe = FALSE ;
  if(bDebugMe) 
    {
      SmBrep *pBrep = this->GetBrep();

      smgfx_Erase();
      smgfx_SetLook( 1,2, 0,0,1 ) ; if(pBrep) pBrep->Draw(TRUE); sm_GraphicsLoop();  
      smgfx_SetLook( 2,4, 0,0,0 ) ; this ->Draw(); sm_GraphicsLoop();
      smgfx_SetLook( 3,5, 0,1,0 ) ; pLoop->Draw(3,FALSE,NULL,FALSE); sm_GraphicsLoop();
      sm_GraphicsLoop();
    }
#endif // SM_DEBUG_CODE

  // arrive here for EdgeLoop type Loops
  // Work from the Edgeuses of pLU1.

  // locals
  ULONG ii, jj;
  SmEdgeuse *pEUData[256];
  SmTArray<SmEdgeuse*> sEdgeuses(256,pEUData);
  pLU1->GetEdgeuses(sEdgeuses);

  // The following optimizations are obsolete.  The caller is not necessarily
  // looking for whether this is supposed to be an inner or outer loop,
  // they want to know the orientation, often to check whether it's wrong and
  // in need of repair. [B586]
//
//  // Now check for non-closed loops.
//  // If a loop in a face is not closed, then every edge will have
//  // that face on both sides, hence the number of occurences of
//  // that face will be two.
//  // There is another way to have two occurences on the same face:
//  // if an edge is a seam.  In that case, it's an outer loop.
//  // So: if every edge in a loop has two occurences in the face,
//  // and is not a seam, then the loop is not closed, hence inner.
//  // As a corollary, if any Edge is a seam, then return Outer.  [B531]
//
//  SmBoolean bMustBeInner = TRUE;
//  SmBoolean bIsOnSeam    = FALSE;
//
//  for (ii=0; ii<sEdgeuses.GetSize(); ii++)
//    {
//      SmEdgeuse *pEU = sEdgeuses[ii];
//      SmEdge    *pE  = pEU->GetEdge();
//
//      // Do this only if we're using uv trim curves.
//      if ( ! bDo3DLoopComputation )
//      {
//        if ( pE->IsSeam(*GetSurface()) )
//          {
//            bMustBeInner = FALSE;
//            bIsOnSeam = TRUE;
//            break;
//          }
//      }
//
//      // Not a seam.  Get number of times this edge bounds this Face.
//      if ( bMustBeInner == TRUE )
//      {
//        ULONG lNumUsed = pE->GetNumberFaceOccurances(this);
//
//        SM_ASSERT(lNumUsed > 0); // It had better be on this face.
//        if ( lNumUsed != 2 )
//          {
//            bMustBeInner = FALSE;
//            if ( ! bDo3DLoopComputation )
//              { break; }   // else keep looking for Seam Edges.
//          }
//      }
//
//    } // end iter every loop->Edgeuse checking for non-closed loops.
//
//  if ( bIsOnSeam )
//    {
//      reLoopOrient = SM_OT_SAME;
//      return SM_SUCCESS;
//    }
//  if ( bMustBeInner )
//    {
//      reLoopOrient = SM_OT_OPPOSITE;
//      return SM_SUCCESS;
//    }
//

  // Integrate UVArea within the loop by walking the UVTrimCurves to determine its orientation.

  // First, try it in uv space, using uv trim curves from the Edgeuses.
  // If all uv trim curves are available, uv space is easier.  [B513 556 557]
  // If any uv trim curve does not already exist, then either try creating them
  // (if bDo3DLoopComputation is False) or skip to the 3d algorithm (otherwise).

  SmTArray< SmCurve* > sUVCurves;
  SmTArray< SmEdgeuse* > sEUs;
  SmTArray< SmBoolean > sSenses;
  SmCurve   *pUVCurve;
  SmStatus   eStat = SM_SUCCESS;
  SmBoolean  bUVCurvesOk = TRUE;

  pLU1->GetEdgeuses( sEUs );

  // for every Loop->Edgeuse
  for(ii=0;ii<sEUs.GetSize();ii++)
    {
      SmEdgeuse* pEU = sEUs[ii];

      // Don't create a UVTrimCurve if asked not to.  [B586 B592]
      if ( bDo3DLoopComputation )
        { pUVCurve = pEU->GetUVTrimCurve(); }
      else // create missing UVTrimCurves
        { eStat    = pEU->GetOrCreateUVTrimCurve( pUVCurve ); }

      // no work - UVTrimCurve is missing - go try the 3d algorithm
      if ( pUVCurve == NULL || eStat != SM_SUCCESS )
        {
          bUVCurvesOk = FALSE; // If a problem with any uv curve, force 3d computation.
          break;
        }

      // build UVTrimCurve data arrays
      sUVCurves.Add( pUVCurve );
      sSenses  .Add( pEU->GetOrientation() == SM_OT_SAME );

      // Check if UVTrimCurves are connected in UV space (not always near singularities).  
      if(ii > 0)
        {
          // If not, then don't use uv curves - try 2d algorithm
          if ( !sm_AreConnected( sEUs[ii-1], pEU ) )
            {
              bUVCurvesOk = FALSE;
              break;
            }
        } // end EdgeEnd-to-EdgeEnd
    } // end iter every Loop->Edgeuse

  // Check LastEdge-to-FirstEdge UVSpace end-to-end connectedness.
  if(bUVCurvesOk )
    {
      if ( ! sm_AreConnected( sEUs.GetLast(), sEUs[0] ) )
        {
            bUVCurvesOk = FALSE;
        }
    } // end LastEdge-to-FirstEdge UVSpace end-to-end connectedness check

  // when all the UVTrimCurves are available, connected, and form a closed loop in UVSpace
  if(bUVCurvesOk )
    {
      // walk all UVTrimCurves to determine if this is a CCW or CW loop
      SmVector3d sNormal(0,0,1);
      eStat = SmCompositeCurve::ComputeProjectedLoopOrientation(sUVCurves,
                                                                sSenses,
                                                                sNormal,
                                                                reLoopOrient,
                                                                pUVBounds );

      if( (eStat == SM_SUCCESS) && (reLoopOrient != SM_OT_UNKNOWN) )
        { return SM_SUCCESS; }

    } // end UVTrimCurves are good to use for computation check

  // arrive here when UVTrimCurves are not good for computation. Try 3d algorithm.
  bDo3DLoopComputation = TRUE;

  // When asked, or when the uv-space compuatation didn't work, work in 3d.
  // This is somewhat more expensive and should be used only when
  // we don't want to use uv trim curves.

// GWC:FEWER_SURFACE_COPIES_CHANGE - TODO see if surface copy can be replaced
//                                 with temporary change of m_pOwner = NULL

  // get temporary face->Surface copy
  SmSurface *pSurf = GetSurface();
  SmSurface *pSurfCopy;
  SER(pSurf->Copy(*GetContext(),pSurfCopy));
  NER(pSurfCopy);
  SmObjDelete sCleanCopy(pSurfCopy);

  SmExtent2d sFaceDomain = this->GetUVDomain();
  SmExtent2d sSurfDomain = pSurf->GetNaturalUVDomain();

  // Get last edgeuse endPosition (3d).
  SmSolutionArray sSolutions;
  SmPoint3d sPoint;
  SmVector3d sLastTangent, sTangent;
  SER(sEdgeuses.GetLast()->NormalizedEvaluate
                            (1.0,              // in : 0 to 1 target param value (accounts for orientation)
                             FALSE,            // in : TRUE = Eval UVTrimCurve for a Surface UV Value
                                               //      FALSE= Eval Curve for an XYZ evaluation
                             sPoint,           // out: UV or XYZ value along Edgeuse for param
                             &sLastTangent));  // out: 1st UV or XYZ deriv along Edgeuse at param point,
                                               //      NULL to ignore, default:[NULL]

  // DropPoint to Surface (why not use UVTrimCurve GuessPoint)
  SER(pSurfCopy->GlobalPointSolve( sFaceDomain, SM_SO_MINIMIZE, sPoint,
                                   GetTolerance(), NULL, SM_SR_SINGLE,
                                   sSolutions));

  SmPoint2d sUV1, sUV2;
  SmPoint2d *pUVGuess = & sUV1;

  // No, don't do this, see note in header comments.
  //if ( sSolutions.GetSize() > 1 )  // Seam check
  //{
  //    sUV1.Set( sSolutions[0].m_vStart[0], sSolutions[0].m_vStart[1] );
  //    if ( sSurfDomain.IsPoint2dOnBoundary( sUV1 ) )
  //      {
  //      reLoopOrient = SM_OT_SAME;
  //      return SM_SUCCESS;
  //      }
  //}

  if ( sSolutions.GetSize() == 1 )
    {
      sUV1.Set( sSolutions[0].m_vStart[0], sSolutions[0].m_vStart[1] );
    }
  else
    {
      sUV1.Set( 0, 0 ); // This will add zero to the sum.
      pUVGuess = NULL;  // Don't use this as a guess.
    }

#ifdef SM_DEBUG_CODE
  if(bDebugMe) 
    {
      smgfx_SetLook(4, 4, 1, 0, 0); sPoint.Draw(); sm_GraphicsLoop();
      sm_GraphicsLoop();
    }
#endif // SM_DEBUG_CODE

  SmBoolean bSuccess;
  double dTotalArea = 0.0;
  double dThisTriArea, dGap;
  SmBoolean bIsMulti;
  SmPoint2d sVeryFirstUV;
  SmBoolean bFirstUVSet=FALSE;

  SmVector2d sParamShift( 0, 0 );

  SmBoolean bClosedU = pSurfCopy->IsClosed( sSurfDomain, SM_SP_U );
  SmBoolean bClosedV = pSurfCopy->IsClosed( sSurfDomain, SM_SP_V );

  // for every edgeuse
  for(ii=0; ii<sEdgeuses.GetSize(); ii++)
    {
      SmEdgeuse *pEU = sEdgeuses[ii];

#ifdef SM_DEBUG_CODE
      if (bDebugMe) 
        {
          if ( FALSE )
            { smgfx_Erase(); }
          smgfx_SetLook( 2,3, 1,0,0 ); pEU->Draw(); sm_GraphicsLoop();
          sm_GraphicsLoop();
        }
#endif // SM_DEBUG_CODE

      static constexpr ULONG lNumSamples = 20;
      // For 21 sample points along the curve - integrate signed area in uv space.
      for(jj=0; jj<=lNumSamples; jj++)
        {
          // get the Curve Position and Tangent
          double dParam = jj / (double)lNumSamples;
          SER(pEU->NormalizedEvaluate(dParam,        // in : 0 to 1 target param value (accounts for orientation)
                                      FALSE,         // in : TRUE = Eval UVTrimCurve for a Surface UV Value
                                                     //      FALSE= Eval Curve for an XYZ evaluation
                                      sPoint,        // out: UV or XYZ value along Edgeuse for param
                                      &sTangent)) ;  // out: 1st UV or XYZ deriv along Edgeuse at param point,
                                                     //      NULL to ignore, default:[NULL]

          // DropPoint to Surface to get uv.
          // Note, DropPoint() will step across seams.  sm_CheckSeamCrossing() assumes that.
          SER( pSurfCopy->DropPoint( sPoint, sFaceDomain, pUVGuess, bSuccess, sUV2, dGap, bIsMulti ));

#ifdef SM_DEBUG_CODE
          if (bDebugMe) 
            {
              smgfx_SetLook( 4,4, 1,0,0 ); sPoint.Draw(); sm_GraphicsLoop();
              smgfx_SetLook( 3,3, 0,0,1 ); sUV2.Draw(); sm_GraphicsLoop();
              sm_GraphicsLoop();
            }
#endif // SM_DEBUG_CODE

          // when there is a solution
          if ( bSuccess )
            {
              if ( bFirstUVSet == FALSE && pUVGuess != NULL )
                {
                  sVeryFirstUV = sUV1;
                  bFirstUVSet  = TRUE;
                }
              sm_CheckSeamCrossing( sUV1, sUV2, pSurfCopy, sSurfDomain, bClosedU, bClosedV, sParamShift );

              // Apply the correction to put the uv points into the same period as they started.
              sUV1 += sParamShift;
              sUV2 += sParamShift;

              // 'Area': cross product of vectors from origin to sUV1 and to sUV2
              // is (twice) the signed area of the triangle  [ origin - sUV1 - sUV2 ].
              dThisTriArea = sUV1.x * sUV2.y  -  sUV1.y * sUV2.x;

              dTotalArea += dThisTriArea;

              // Shift back into the surface period, for dropping.
              sUV2 -= sParamShift;  // (Don't have to do sUV1 because of the next statement...)

              // Set up for next iter.
              sUV1 = sUV2;
              pUVGuess = &sUV1;

            } // end if good drop
            else
              { pUVGuess = NULL; } // Use Global solve for next point.

        } // end iter every sample point
    } // end iter every edgeuse

  // Catch the final-point-to-first-point span.  The final point will usually
  // be the same as the first point, but could span a pole.
  sUV2 += sParamShift;
  dThisTriArea = sUV2.x * sVeryFirstUV.y  -  sUV2.y * sVeryFirstUV.x;
  dTotalArea += dThisTriArea;

  // Positive area means CCW, Negative is CW.
  // When intergration scheme wasn't good enough - return UNKNOWN

  double dDomainArea = sFaceDomain.XLength() * sFaceDomain.YLength();
  double dAreaRatio  = 1e+8;  // Pretty arbitrary: 1/10,000 of the domain in each dimension.
                              // Note 1e+4 is too small.  [my_offset_demo iter:14]

  if  (dTotalArea > dDomainArea / dAreaRatio )
    { reLoopOrient = SM_OT_SAME; }

  else if(dTotalArea < -dDomainArea / dAreaRatio )
    { reLoopOrient = SM_OT_OPPOSITE; }

  else
    { reLoopOrient = SM_OT_UNKNOWN; }

  return SM_SUCCESS;


  // Note, the rest of this method should be obsolete.  [B556]
  // It's also unreachable now.  [B586]

//  // Arrive here when we are able to walk the uv trim curves to
//  // decide if its a CCW OuterLoop or a CW InnerLoop.
//
//  // locals
//  ULONG                         sLIData[32];
//  SmTArray<ULONG>               sLoopsIndex(32,sLIData);
//  SmTArray<SmBSplineCurve*>     sFaceTrimBoundary;
//
//  // Get copies of all UVTrimCurves in Loop traversal order
//  //  This is just lazy - we only need an ordered list of all
//  //                    edges ready to be walked.
//  //                    GWC:TODO - This should
//  //                    be done without copying curves.
//  SER(CreateOrientedTrimBoundary(*GetContext(),
//      TRUE,                // in : Get UVTrimCurve Copies
//      TRUE,                // in : Create UVTrimCurves to jump SurfaceSingularity gaps as needed
//      sLoopsIndex,         // out: number of loops and number of curves in each loop
//      sFaceTrimBoundary,   // out: ordered UVTrimCurve copies
//      pLoop));             // in, opt: Create trim boundary for this loop only.
//
//  // delete all curve copies when leaving this scope
//  SmObjsDelete<SmBSplineCurve*> sClean1(&sFaceTrimBoundary);
//
//  // Load sTrimBoundary array with curves from loop of interest.
//  SM_PTR_ARRAY( sTrimBoundary, SmCurve, 32 );
//  for ( ii=0; ii<sFaceTrimBoundary.GetSize(); ii++ )
//    { sTrimBoundary.Add( SM_CAST_PTR( SmCurve, sFaceTrimBoundary[ii] )); }
//
//  // error - no edges are found
//  if (sTrimBoundary.GetSize() == 0) { SER(SM_ERR); }
//
//  // load Boolean array with TRUE value for each sTrimBoundaryCurve
//  sSenses.ReSet();
//  sSenses.InsertAt(0,TRUE,sTrimBoundary.GetSize());
//
//  // walk all UVTrimCurves to determine if this is a CCW or CW loop
//  SmVector3d sNormal(0,0,1);
//  SER(SmCompositeCurve::ComputeProjectedLoopOrientation(sTrimBoundary,
//                                                      sSenses,
//                                                      sNormal,
//                                                      reLoopOrient,
//                                                      pUVBounds));
//  // all done
//  return SM_SUCCESS;

} // end SmFace::ComputeLoopOrientation

