//         || dEndAng3dDeg   < 5.0)
//        { continue ; }
//  
//      // Skip UVTrimLines that don't run from UVDomain min to max when working with MissingSeams
//      if(   pFaceProps->m_eBadMissingSeam == SM_SP_U
//         || pFaceProps->m_eBadMissingSeam == SM_SP_BOTH) 
//        { // UVTrimLine should run from UVDomain.MinV to UMDomain.MaxV
//          if(   FALSE == SM_ARE_SAME(sTrimLineStartUV.y, pFaceProps->m_sNaturalUVDomain.GetVMin())
//             || FALSE == SM_ARE_SAME(sTrimLineEndUV.y,   pFaceProps->m_sNaturalUVDomain.GetVMax()))
//            { continue ; }
//        }
//      if(   pFaceProps->m_eBadMissingSeam == SM_SP_V
//         || pFaceProps->m_eBadMissingSeam == SM_SP_BOTH) 
//        { // UVTrimLine should run from UVDomain.MinU to UMDomain.MaxU
//          if(   FALSE == SM_ARE_SAME(sTrimLineStartUV.x, pFaceProps->m_sNaturalUVDomain.GetUMin())
//             || FALSE == SM_ARE_SAME(sTrimLineEndUV.x,   pFaceProps->m_sNaturalUVDomain.GetUMax()))
//            { continue ; }
//        }
//  
//      // Build a CrvClassification for UVTrimLine's CrvOnSurf
//  
//      // upcoming CurveClassification locals
//      SmBoolean bModifiedCurve = FALSE ;
//      SmBoolean bUVSpaceOkay   = TRUE ; 
//  
//      // set CrvClassification object with current Curve to Classify
//      pCrvClassification->ReSet(  rpCrvOnSurf, 
//                                &(rpCrvOnSurf->GetNaturalInterval()), 
//                                  rpUVTrimLine,
//                                  pFaceProps->m_sXSectTol3d/2.0) ;
//  
//      // set Classify to Two given Loops Only
//      pCrvClassification->SetTgtLoopsOnly(TRUE) ;
//      pCrvClassification->AddTgtLoop((SmLoop*)pLoop) ; 
//      pCrvClassification->AddTgtLoop((SmLoop*)pOptOther) ; 
//  
//  #ifdef SM_DEBUG_CODE
//      if(bDebugMe)
//        {
//          pFaceProps->Dump() ; 
//          SmBrep * pBrep = pFaceProps->m_pFace ? pFaceProps->m_pFace->GetBrep() : NULL ; 
//  
//          smgfx_Erase() ;
//          smgfx_SetLook(1,2, 0,0,1) ; if(pBrep) pBrep->Draw(TRUE) ; sm_GraphicsLoop() ;
//          pFaceProps->Draw(TRUE) ; sm_GraphicsLoop() ; // sSheetColor         - def:[ 0, 1, 1]
//                                                       // sCrossedSeamColor   - def:[ 1, 0, 1]
//                                                       // sMissingSeamColor   - def:[ 1, 0, 0]
//                                                       // sMissingPoleColor   - def:[ 0, 0, 1]
//                                                       // sBadOrientLoopColor - def:[.3,.3,.3]
//                                                       // sNoArea_LoopColor   - def:[ 0, 0, 0]
//          smgfx_SetLook(2,3, 1,0,0) ; if(pLoop) pLoop->Draw() ; sm_GraphicsLoop() ; 
//          smgfx_SetLook(3,4, 1,0,0) ; if(rpCrvOnSurf) rpCrvOnSurf->DrawParams() ; sm_GraphicsLoop() ;
//          sm_GraphicsLoop() ;
//        }
//  #endif // SM_DEBUG_CODE
//  
//      // Classify the sCrvOnSurf against pLoop only
//      pFaceProps->m_pFace->CurveOnClassify
//                           ( TRUE,               // in : TRUE =Do expensive PtClassification for Curves not XSecting any Face->Bndrys 
//                                                 //    : FALSE=classify such points as unknown. (good when Curve is known to be InFace) 
//                            *pCrvClassification, // i/o: contains m_cpCurve to classify, accumulates ivls as they are found. 
//                             TRUE,               // in : TRUE = m_cpCurve and Face->Edges connect to Face where Edge/Face gaps are suspected to exceed XSectTol3d. 
//                                                 //    :      increase XSectTol3d to accomodate large Edge/Face gaps 
//                                                 //    :      (more expensive option - computes Face/Surface gaps) 
//                                                 //    : FALSE= Expect all Face/Edge gaps to be within XSectTol3d, use standard SmTol::GetXSectTol3d tols. 
//                                                 //    : default:[FALSE] 
//                             TRUE,               // in : TRUE = When finding XSectPoints, also check 3d dists 
//                                                 //    : FALSE= When finding XSectPoints, only check 2d dists for XSects 
//                                                 //    : default:[FALSE] 
//                             &bModifiedCurve,    // out: TRUE  = m_cpCurve modified to tighten tols 
//                                                 //    : FALSE = m_cpCurve not modified 
//                                                 //    : When m_cpCurve is modified, the classification is cleared and 
//                                                 //    : rebuilt from scratch - if accumulating classifications from   
//                                                 //    : a sequence of calls, start over. Call CrvClassif->ReSet() and restart sequence. 
//                                                 //    : If this is the only classification call, then CrvClassif is complete 
//                                                 //    : and may be used as returned. 
//                                                 //    : NULL to ignore, default:[NULL] 
//                              bUVSpaceOkay       // in : TRUE = okay to try UVSpace Classification if 3Space classification is dodgey (tolerant cases) 
//                                                 //    : FALSE= don't use UVSpace because UVTrimCurves are not known to be valid, default:[TRUE] 
//                             ) ;
//  
//      // skip classifications with vertex and tangent edge intersections
//  
//  
//      } // end iter OtherLoop->MidEdge->SmpPoints looking for a good UVTrimLine
//  } // end sm_FindTwoLoopBisectorAngle
// End incomplete implementation and probably not needed
  
/*******************************************************************//**
PURPOSE: SmFace::ClassifyLoops() helper function.

NOTES: Given a Loop finds and classifies a UVTrimLine that splits the 
       loop in such a way that its classification against the loop can 
       classify the loop's orientation and NoArea properties.
***********************************************************************/
SmStatus sms_FindAndClassifyLoopBisector
  (ULONG                        lTgtLoopIndx,               // in : Target Loop index (ClassifyCrv UVTrimLine guaranteed to XSect this Loop)
   SmTArray<SmLoop*>          & rLoops,                     // in : list of all Loops to be classified (those marked are already done)
   SmTArray<SmClassifyLoopIO> & rClassifyLoopIOs,           // in : Classification data for marked loops
   SmMarkType                   eMarkType,                  // in : Mark (Context=Loops->Context) to track already classified rTgtLoops 
   SmFace                     * pFace,                      // in : Face owning pLoop 
   SmSurface                  * pSurface,                   // in : pFace's Surface
   SmFaceProps                * pFaceProps,                 // in : cached Face properties (up to SetProps_Stage2) for perfomance
   SmContext                  & rContext,                   // in : context for Tmp Obj construction, can be same as eMarkType context
   SmCurveClassification      * pCrvClassification,         // out: Classification of an acceptable Loop spliting UVTrimLine
   SmCrvOnSurf               *& rpCrvOnSurf,                // out: new ClassifyCurve in pCrvClassification->m_cpCurve (NotOwned: must be deleted by caller)
   SmLine                    *& rpUVTrimLine,               // out: new UVCurve for rpCrvOnSurf in pCrvClassification->m_cpUVCurve1 (NotOwned: must be deleted by caller)
   SmBoolean                  & rbClassifyCrv_StartOnSeam,  // out: TRUE=ClassifyCrv Starts on a Seam boundary, False=Start Not On Seam
   SmBoolean                  & rbClassifyCrv_StopOnSeam,   // out: TRUE=ClassifyCrv Stops on a Seam boundary,  False=Start Not On Seam
   SmTriState                 & rebCLassifyCrv_Closed3d)    // out: ClassifyCrv closed in 3d
{
#ifdef SM_DEBUG_CODE
SmBoolean bDebugMe = FALSE ;
static ULONG lDbgCount = 1 ; lDbgCount++ ;
  if (bDebugMe)
    {
      if(pFaceProps) { pFaceProps->Dump() ; }

      ULONG di ;
      SmBrep * pBrep = pFace ? pFace->GetBrep() : NULL ;
 
      smgfx_Erase() ;
      smgfx_SetLook(1,2, 0,0,1) ; if(pBrep) pBrep->Draw(TRUE) ; sm_GraphicsLoop() ;
      smgfx_SetLook(1,2, 0,0,0) ; if(pFace) pFace->DrawUV() ; sm_GraphicsLoop() ;
      pFaceProps->Draw(TRUE) ; sm_GraphicsLoop() ; // sSheetColor         - def:[ 0, 1, 1]
                                                   // sCrossedSeamColor   - def:[ 1, 0, 1]
                                                   // sMissingSeamColor   - def:[ 1, 0, 0]
                                                   // sMissingPoleColor   - def:[ 0, 0, 1]
                                                   // sBadOrientLoopColor - def:[.3,.3,.3]
                                                   // sNoArea_LoopColor   - def:[ 0, 0, 0]
      smgfx_SetLook(4,5, 1,0,0) ; if(rLoops[lTgtLoopIndx]) rLoops[lTgtLoopIndx]->Draw() ; sm_GraphicsLoop() ; 
      smgfx_SetLook(2,3, 0,1,1) ; for(di=0;di<rLoops.GetSize();di++)
                                    { if(rLoops[di]) rLoops[di]->Draw() ; sm_GraphicsLoop() ; }
      sm_GraphicsLoop() ;
    }
#endif // SM_DEBUG_CODE

  // check state - FaceDomain within SurfaceDomain
  SmExtent2d  sFaceUVDomain = pFace->GetUVDomain() ;
  SmExtent2d  sSurfUVDomain = pSurface->GetNaturalUVDomain() ;
  AERN_MSG(sFaceUVDomain.IsContainedBy(sSurfUVDomain),
           SM_ERR_INVALID_INPUT, _T("SmFace::ClassifyLoops->sms_FindAndClassifyLoopBisector: FaceUVDomain Not contained by SurfaceUVDomain")) ; 

  // init output
  rpCrvOnSurf  = NULL ; 
  rpUVTrimLine = NULL ;
  pCrvClassification->ReSet() ;
  rebCLassifyCrv_Closed3d = SM_TS_UNINIT ;
  rbClassifyCrv_StartOnSeam = FALSE ;
  rbClassifyCrv_StopOnSeam  = FALSE ; 

  // locals
  ULONG ii, jj, kk ;
  SmLoop              * pTgtLoop = rLoops[lTgtLoopIndx] ; 
  SmPoint3d             sPN[2], sSurfNormal, sEdgeEnds[2] ;
  SmPoint2d             sUV[2] ; 
  SmBoolean             bSuccess = FALSE, bFoundInterval = FALSE ;
  SmExtent1d            sTrimInterval ;
  double                dGap ;
  SmBoolean             bIsMulti ;
  SmTArray<SmEdgeuse *> sEdgeuses, sThisEdgeuses ;
  SmTArray<SmPoint3d>   s3dMidPNsOther ;
  SmTArray<SmPoint2d>   sUVMidPNsOther ; 
  SmTArray<ULONG>       sSmpEUOtherIndex ; 
  ULONG                 iSampleCnt = 6 ;  // number of angles checked for UVCurve (even SampleCounts work best)
  SmBoolean             bFound = FALSE ;
  SmObjDelete           sCleanCrvOnSurf, sCleanUVTrimLine ;
  SmPoint3d             sPoint3d ;
  SmEdgeuse           * pLongestEdgeuse = NULL ;
  SmBoolean             bLongestEdgeuseIsSeam = FALSE ;
  double                dMaxEdgeLength=0.0 ; 
  SmBoolean             bDoublyPeriodic = pFaceProps->m_bClosedU && pFaceProps->m_bClosedV ;
  SmCrvOnSurf         * pCrvOnSurf = NULL ;           // new ClassifyCurve in pCrvClassification->m_cpCurve 
  SmLine              * pUVTrimLine = NULL ;          // new UVCurve for pCrvOnSurf in pCrvClassification->m_cpUVCurve1 
  SmPoint2d             sStartUV, sEndUV, sUVDir ;
  
  // get pLoop->Edgeuses for the Target Loop (guarantees UVTrimLine XSects the TgtLoop)
  SmLoopuse * pTgtLoopuse = pTgtLoop->GetLoopuse() ;
  pTgtLoopuse->GetEdgeuses(sEdgeuses) ;          // Returns Edgeuses in CCW order. Unlike GetEdges, two edgeuses
                                                 // from one edge being used in this loopuse both get listed.
  // next - get a 'good' ClassifyCrv UVTrimLine
  // If MissingSeamFace
  //   Classifying UVTrimLine must have proper orientation to properly classify NoArea_Loops -
  //     for MissingSeamU: UVTrimLine must run From UVDomain.VMin To UVDomain.VMax
  //     for MissingSeamV: UVTrimLine must run From UVDomain.UMin To UVDomain.UMax
  // Else Pick any LoopEdge perpendicular bisector to use as the classifying UVTrimLine -
  //   To avoid tolerance problems - if possible 
  //     find a UVTrimLine that only has EdgeCrossingXSections and No VertexXSections far away from singularities

  // For pLoop EveryEdgeuse - evaluate a MidPoint and Try and find A UVTrimCurve orientation that satisfies the above contstraints
  for(ii=0;ii<sEdgeuses.GetSize();ii++)
    {
      // locals and StateChecks
      SmEdgeuse * pEdgeuse  = sEdgeuses[ii] ;
      SmEdge    * pEdge     = pEdgeuse->GetEdge() ;
      AERN_MSG(pEdge!=NULL,  /* if(a!=true) - Signal SM_ERR_ASSERT_FAILURE with msg - return(n) */
               SM_ERR_INVALID_INPUT, _T("SmFace::ClassifyLoops->sms_FindAndClassifyLoopBisector: Given Loop->Edgeuse is not attached to Edge")) ; 

      SmCurve   * pCurve    = pEdge->GetCurve() ;
      AERN_MSG(pCurve!=NULL, 
               SM_ERR_INVALID_INPUT, _T("SmFace::ClassifyLoops->sms_FindAndClassifyLoopBisector: Given Loop->Edge is not attached to Curve")) ; 

      SmExtent1d  sEdgeIvl  = pEdge->GetInterval() ;
      SmExtent1d  sCurveIvl = pCurve->GetNaturalInterval() ;
      AERN_MSG(sEdgeIvl.IsContainedBy(sCurveIvl,SM_EFF_ZERO*1000), 
               SM_ERR_INVALID_INPUT, _T("SmFace::ClassifyLoops->sms_FindAndClassifyLoopBisector: TargetEdgeuse->Edge->Ivl is not contained in TargetEdgeuse->Edge->Curve->Ivl")) ; 

      // Edge midpoint
      pCurve->Evaluate(sEdgeIvl.GetMid(), 1, TRUE, sPN) ;
      
      // Get Edge length - save longest edge in case we have to use it later
      pCurve->EvaluatePoint(sEdgeIvl.GetMin(), sEdgeEnds[0]) ; 
      pCurve->EvaluatePoint(sEdgeIvl.GetMax(), sEdgeEnds[1]) ; 
      double    dEdgeHalfLength0 = sEdgeEnds[0].DistanceBetween(sPN[0]) ; 
      double    dEdgeHalfLength1 = sEdgeEnds[1].DistanceBetween(sPN[0]) ;
      double    dThisLength      = smos_Max(dEdgeHalfLength0, dEdgeHalfLength1) ;
      SmBoolean bEdgeIsSeam   = pEdge->IsSeam() ;
      if(   pLongestEdgeuse == NULL
         || (   dThisLength > dMaxEdgeLength
             && (   bLongestEdgeuseIsSeam == FALSE
                 || bEdgeIsSeam == TRUE)))
        {
          dMaxEdgeLength        = dThisLength ;
          pLongestEdgeuse       = pEdgeuse ;
          bLongestEdgeuseIsSeam = bEdgeIsSeam ; 
        }

      // skip strut, crack, and seam edges - count the edgeuses on this Edge in this loop, if even - its a crack, strut, or seam edge
      SmTArray<SmEdgeuse*> sEdgeusesInLoop ; 
      pEdge->GetEdgeuses(sEdgeusesInLoop, NULL, pTgtLoopuse) ;
      if(smos_IsEven(sEdgeusesInLoop.GetSize()))
        {
          // when more edges remain to be tested - skip this strut, crack, or seam edge
          if(ii < sEdgeuses.GetSize()-1)
            { continue ; }
          else if(pLongestEdgeuse) // all edges fail culling tests - use the longest one seen
            { // arrive here for valid cases:
              //   closed sphere: 1 seam edge and two pole vertices - no non-seam edges
              //   closed torus : 2 seam edges and one pole vertex - no non-seam edge
              // the ok cases here all seem to be natural trimmed surfaces and should have a LongestEdgeuse that's a seam.
              
              // code this section assuming that a longest seam edge has been seen - extend the algorithm if that proves to be false
              
              // check - pLongestEdgeuse is a seam
              SM_ASSERT_MSG(bLongestEdgeuseIsSeam == TRUE, _T("SmFace::ClassifyLoops->sms_FindAndClassifyLoopBisector - all Loop faces are struts, cracks, or seam and Longest is not a Seam - algorithm needs extension")) ;

              // could add check to verify that the ok loop cases are naturally trimming loops

              // Just use the LongestEdgeuse seen
              pEdgeuse = pLongestEdgeuse ;
            }
          else
            {
              SM_ASSERT_MSG(ii<sEdgeuses.GetSize()-1,
                            _T("SmFace::ClassifyLoops->sms_FindAndClassifyLoopBisector - skipping LastEdge because it's a strut or crack - algorithm needs to be extended to recover from this")) ; 
              continue ;
            }
        } // end pEdge is a Struct, Crack or Seam check

      // skip edge evaluations on singularities
      ULONG lIndx = SM_UNDEF_ULONG ; 
      if(   pFaceProps->m_lPoles != SM_SS_NONE 
         && pFaceProps->m_sPolePoints.FindElementInMaskedArray(sPN[0], pFaceProps->m_lPoles, lIndx))
        { 
          // when more edges remain to be tested - skip this edge on Singularity
          if(ii < sEdgeuses.GetSize()-1)
            { continue ; }
          else if(pLongestEdgeuse) // all edges fail culling tests - use the longest one seen
            { SM_DBG_WARN(_T("SmFace::ClassifyLoops->sms_FindAndClassifyLoopBisector - All Edges culled, using longest edge - algorithm needs to be extended to recover from this")) ; 
              pEdgeuse = pLongestEdgeuse ;
            }
          else
            {
              SM_ASSERT_MSG(ii<sEdgeuses.GetSize()-1,
                            _T("SmFace::ClassifyLoops->sms_FindAndClassifyLoopBisector - skipping LastEdge because it's on a singularity - algorithm needs to be extended to recover from this")) ; 
              continue ;
            }
        } // end EdgeSmpPt is on the SurfSingularity check

      // skip short edges - if all edges are short use the longest edge
      if(   (dEdgeHalfLength0 < SmTol::GetZoneTol3d(pEdge) * 10.0)  // can be any number just looking for any def of short
         || (dEdgeHalfLength1 < SmTol::GetZoneTol3d(pEdge) * 10.0)) // can be any number just looking for any def of short
        { 
          // when more edges remain to be tested - skip this short edge
          if(ii < sEdgeuses.GetSize()-1)
            { continue ; }
          else if(pLongestEdgeuse) // all edges fail length test - use the longest one seen
            { SM_DBG_WARN(_T("SmFace::ClassifyLoops->sms_FindAndClassifyLoopBisector - All Edges too small, using longest edge - DegenFace? BadTolVal?")) ; 
              pEdgeuse = pLongestEdgeuse ;
            }
          else
            { SM_DBG_WARN(_T("SmFace::ClassifyLoops->sms_FindAndClassifyLoopBisector - skipping LastEdge because it's short - algorithm needs to be extended to recover from this")) ; 
              continue ;
            }
        } // end skip small edge check

      // arrive here when we have a likely Edgeuse and EdgeuseSmpPt from which to run the classification
      
      // when UVTrimCurve is available - use UVTrimCurve to get pUVGuess
      SmPoint3d   sUVGuess3d ; 
      SmPoint2d   sUVGuess, * pUVGuess = NULL ; 
      SmCurve  * pUVTrimCurve = pEdgeuse->GetUVTrimCurve() ; 
      if(pUVTrimCurve != NULL) { pUVTrimCurve->EvaluatePoint(sEdgeIvl.GetMid(), sUVGuess3d) ;
                                 sUVGuess = sUVGuess3d ; 
                                 pUVGuess = &sUVGuess ;
                               }

      // Drop Edge->MidPoint to Surface to UVPoint ThroughPoint for upcoming UVTrimCurve.
      SER( pSurface->DropPoint( sPN[0],        // in : target point to drop
                                sSurfUVDomain, // in : target surface domain
                                pUVGuess,      // in : When given, uses only local solves
                                bSuccess,      // out: TRUE=Point dropped successfully, FALSE=didn't
                                sUV[0],        // out: drop result UVPoint
                                dGap,          // out: distance of found point to Pt to drop
                                bIsMulti)) ;   // out: TRUE = solution is multivalued, FALSE = Single valued   
                                               // in : SM_SO_MINIMIZE = [default] allow nonNormal drops near boundaries
                                               //      SM_SO_NORMALIZE= exclude nonNormal drops near boundaries
                                               //      SM_SO_INTERSECT= point must be on surface, to Tol
      // skip this edgeuse if something goes wrong
      if(bSuccess != TRUE)
        { 
          SM_ASSERT_MSG(ii<sEdgeuses.GetSize()-1,
                        _T("SmFace::ClassifyLoops->sms_FindAndClassifyLoopBisector - skipping LastEdge because DropSmpPt failed - algorithm needs to be extended to recover from this")) ; 
          continue ; 
        }

      // Drop EdgeTan to Surface
      pSurface->DropVectors(sUV[0], TRUE, TRUE, 1, &(sPN[1]), &(sUV[1])) ;
      
      // Surface normal at Drop Point
      pSurface->EvaluateNormal(sUV[0], TRUE, TRUE, sSurfNormal) ; 

      // arrive here when: bSuccess == TRUE when sUV[UVPoint, UVVec] and sSurfNormal are set
      //                 bSuccess == FALSE when something went wrong and no dropp UVPoints were found - quit
      AERN_MSG(bSuccess == TRUE, 
               SM_ERR_METHOD_FAILURE_QUITING, _T("SmFace::ClassifyLoops->sms_FindAndClassifyLoopBisector - Failed to drop an EdgeMidPoint to Surface - quiting")) ;

      // Classify a sequence of UVCurves until one that is found that only has crossing-intersections with the edges of the loop
      //    if the Face has a missing seam make sure the UVCurve runs 
      //    don't let the UVCurve be tangent to the ClassifyCurve at the sample point

      // Rotation Range to search for 'good' classify curve
      double dDropTanDeg = SM_RAD2DEG(smos_ArcTangent2( sUV[1].y, sUV[1].x)) ;  // Rtn: [-Pi to Pi] => [-180 to 180]
      SmExtent1d sAngRangeDeg(dDropTanDeg-90, dDropTanDeg+90) ;
      SmBoolean bMissingSeamSampling = FALSE ;

      // Adjust sAngRangeDeg as needed:
      //   when MissingSeam curve, only consider UVCurves that run from the min to the max side of the UVDomain as:
      //            for MissingSeamU: UVTrimLine must run From UVDomain.VMin To UVDomain.VMax
      //            for MissingSeamV: UVTrimLine must run From UVDomain.UMin To UVDomain.UMax
      //   (For doubly periodic surfaces, i.e. Tori only build IsoParam UVTrimLines runing from Seam to Seam: bDoublyPeriodic==TRUE)
      //   (we skip the uninit case where m_eMisingSeam == SM_SP_UNKNOWN)
      if(bDoublyPeriodic == TRUE)  // doubly periodic surface -> ClassifyCrv must run SeamToSeam and be Closed3d
        {
          sAngRangeDeg.SetMinMax(0,90) ; 
          iSampleCnt = 2 ;
          rbClassifyCrv_StartOnSeam = TRUE ; // TRUE = ClassifyCrv Starts on Seam Boundary
          rbClassifyCrv_StopOnSeam  = TRUE ; // TRUE = ClassifyCrv Stops on Seam Boundary
        }
      else if(   pFaceProps->m_eBadMissingSeam == SM_SP_U
              || pFaceProps->m_eBadMissingSeam == SM_SP_V
              || pFaceProps->m_eBadMissingSeam == SM_SP_BOTH)
        {
          double    dCornerAngDeg[4] ; // dCornerDistSq[4] ; 
          SmPoint2d sCornerUV ;

          // remember we went through this branch - later we pick the sampling order based on this value
          bMissingSeamSampling = TRUE ;

          // get the angle to every corner from the DropPoint
          for(jj=0;jj<4;jj++)
            {
              switch(jj) { case 0 : { sCornerUV.Set(sFaceUVDomain.GetUMin(), sFaceUVDomain.GetVMin()) ; } break ; 
                           case 1 : { sCornerUV.Set(sFaceUVDomain.GetUMax(), sFaceUVDomain.GetVMin()) ; } break ; 
                           case 2 : { sCornerUV.Set(sFaceUVDomain.GetUMax(), sFaceUVDomain.GetVMax()) ; } break ; 
                           case 3 : { sCornerUV.Set(sFaceUVDomain.GetUMin(), sFaceUVDomain.GetVMax()) ; } break ;
                         }
              SmVector2d sCornerDir(sCornerUV - sUV[0]) ;                    
              // dCornerDistSq[jj] = sCornerDir.LengthSquared() ;            
              dCornerAngDeg[jj] = SM_RAD2DEG(smos_ArcTangent2(sCornerDir.y, sCornerDir.x)) ; // Rtn: -Pi to Pi => -180, 180 

              // place all angles in range 0 to 360 picking 0.0 for case 2 and 360.0 for case 1 when angle is 0.0
              switch(jj) { case 0 : { // range 180 to 270                                             
                                      if(dCornerAngDeg[jj] < (180 - SM_EFF_ZERO)) { dCornerAngDeg[jj] += 360.0 ; }
                                      SM_ASSERT_MSG(SM_IS_CONTAINED(dCornerAngDeg[jj], 180.0, 270.0), 
                                                    _T("SmFace::ClassifyLoops->sms_FindAndClassifyLoopBisector: PeriodicVal Err - bug needs fixing")) ; 
                                    } break ; 
                           case 1 : { // range 270 to 360
                                      if(dCornerAngDeg[jj] < (270 - SM_EFF_ZERO)) { dCornerAngDeg[jj] += 360.0 ; }
                                      SM_ASSERT_MSG(SM_IS_CONTAINED(dCornerAngDeg[jj], 270.0, 360.0), 
                                                    _T("SmFace::ClassifyLoops->sms_FindAndClassifyLoopBisector: PeriodicVal Err - bug needs fixing")) ; 
                                    } break ; 
                           case 2 : { // range   0 to  90
                                      SM_ASSERT_MSG(SM_IS_CONTAINED(dCornerAngDeg[jj], 0.0, 90.0), 
                                                    _T("SmFace::ClassifyLoops->sms_FindAndClassifyLoopBisector: PeriodicVal Err - bug needs fixing")) ; 
                                    } break ; 
                           case 3 : { // range  90 to 180
                                      SM_ASSERT_MSG(SM_IS_CONTAINED(dCornerAngDeg[jj], 90.0, 180.0), 
                                                    _T("SmFace::ClassifyLoops->sms_FindAndClassifyLoopBisector: PeriodicVal Err - bug needs fixing")) ; 
                                    } break ;
                         }

              if(dCornerAngDeg[jj] < 0.0) { dCornerAngDeg[jj] += 360.0 ; }
            }

          // adjust the UVCurve angle range so only UVCurves that span the UVDomain in the proper direction are considered
          double dMin, dMax ; 
          if(pFaceProps->m_eBadMissingSeam == SM_SP_U) { dCornerAngDeg[0] -= 180 ;
                                                         dCornerAngDeg[1] -= 180 ;
                                                         dMin = smos_Max(dCornerAngDeg[0], dCornerAngDeg[2]) ;
                                                         dMax = smos_Min(dCornerAngDeg[1], dCornerAngDeg[3]) ;
                                                       }
          else                                         { dCornerAngDeg[0] += 180 ;
                                                         dCornerAngDeg[2] += 360 ;
                                                         dCornerAngDeg[3] += 180 ;
                                                         dMin = smos_Max(dCornerAngDeg[1], dCornerAngDeg[3]) ;
                                                         dMax = smos_Min(dCornerAngDeg[0], dCornerAngDeg[2]) ;
                                                       }
          sAngRangeDeg.SetMinMax(dMin, dMax) ;         

         // shorten the rotation angle to back off the corners (avoids vertex intersections
         sAngRangeDeg.ExpandRelative(-.05) ; 

        } // end MissingSeam need to adjust the rotation angle range check

      // for every trial angle
      for(jj=0;jj<iSampleCnt;jj++)
        {
          // Make next CrvOnSurf to classify from DropPoint:[UVPoint, UVVec]  
          // if bMissingSeamSampling == TRUE - start samples at middle of interval (interval mid is near 90 deg to EdgeTangent)
          //    bMissingSeamSampling == FALSE - start samples at min of interval (interval min is 90 deg to EdgeTangent)
          ULONG  lSmpInc   = bMissingSeamSampling ? iSampleCnt/2 : 0 ;
          ULONG  lTgtIndx  = (jj+lSmpInc)%(iSampleCnt) ;
          double dAngleDeg = sAngRangeDeg.Evaluate(  (lTgtIndx == 0) ? 0.0
                                                   : (lTgtIndx == iSampleCnt-1) ? 1.0
                                                   : (double)lTgtIndx/(double)(iSampleCnt-1)) ;

          // avoid ClassifyCurves nearly tangent to EdgeCurve at DropPoint
          if(smos_Fabs(dAngleDeg - dDropTanDeg) < 5.0)
            { dAngleDeg += 5.0 ; }

          // for doubly periodic surfaces - only build isolines - (iSampleCnt already set to 2)
          if(bDoublyPeriodic==TRUE) { dAngleDeg = (jj == 0) ? 0.0 : 90.0 ; }
          
          // Map dAngleDeg to a dir vector
          sUVDir.Set(smos_CosDeg(dAngleDeg), smos_SinDeg(dAngleDeg)) ;

          // build UVLine to use as the UVClassificationCurve
          sSurfUVDomain.IntersectWithInfiniteLine(sUV[0], sUVDir, bFoundInterval, sTrimInterval) ;
          sStartUV = sSurfUVDomain.ClampPoint2d( sUV[0] + sTrimInterval.GetMin() * sUVDir ); // shouldn't need clamp but included to take care of numerical roundoff
          sEndUV   = sSurfUVDomain.ClampPoint2d( sUV[0] + sTrimInterval.GetMax() * sUVDir ); // shouldn't need clamp but included to take care of numerical roundoff

          pUVTrimLine = new (rContext) SmLine(sStartUV, sEndUV, 2, &rContext) ;
          sCleanUVTrimLine.ReplaceObj(pUVTrimLine) ; // deletes previously stored pUVTrimLines

          // Map UVClassificationCurve to 3d through the Face->Surface
          pCrvOnSurf = new (rContext) SmCrvOnSurf(*pUVTrimLine, *pSurface, &sSurfUVDomain, 0, &rContext) ; // 0 = NothingOwned, delete nothing when destructed
          sCleanCrvOnSurf.ReplaceObj(pCrvOnSurf) ;   // deletes previously stored pCrvOnSurfs

          // upcoming CurveClassification locals
          SmBoolean  bModifiedCurve = FALSE ;
          SmBoolean  bUVSpaceOkay   = FALSE ; // has to be FALSE - pCrvOnSurf contains pUVTrimLine and can be safely dropped to UVSpace
                                              // however CurveOnClassify() when allowed to work in UV space
                                              //  will also call SmFace::EdgeCurveOnClassify for existing edges
                                              //   if those edges are Crossing a Seam - calls to Edge->Edgeuse->GetOrCreateUVTrimCurve() will fail 
          SmExtent1d sCrvOnSurfIvl  = pCrvOnSurf->GetNaturalInterval() ;

          // set CrvClassification object with current ClassifyCrv
          pCrvClassification->ReSet( pCrvOnSurf,                // default: NotOwned so repeated ReSets don't double delete m_pCurve
                                    &sCrvOnSurfIvl, 
                                     pUVTrimLine,
                                     pFaceProps->m_sZoneTol3d) ;

          // set Classify to Target TgtLoops only
          pCrvClassification->SetTgtLoopsOnly(TRUE) ;

          // build the TgtLoop list (all unmarked loops and the outer loop if it exists and is known)
          for(kk=0;kk<rLoops.GetSize();kk++)
            {
              // skip marked loops (except an identified outer loop or potential outer loop)
              if(   rLoops[kk]->IsMarked(eMarkType)
                 && rClassifyLoopIOs[kk].m_eContainmentType != SM_CMT_OUTERLOOP
                 && rClassifyLoopIOs[kk].m_eContainmentType != SM_CMT_TOPLOOP
                 && rClassifyLoopIOs[kk].m_eContainmentType != SM_CMT_BOTLOOP)
                { continue ; }

              // add Unmarked or Outer Loop to CrvClassification Tgt list
              pCrvClassification->AddTgtLoop(rLoops[kk]) ;
            } // end iter kk every Loop building current TgtLoop list

#ifdef SM_DEBUG_CODE
          if(bDebugMe)
            {
              pFaceProps->Dump() ; 

              ULONG di ; 
              SmBrep                  * pBrep   = pFace ? pFace->GetBrep() : NULL ;
              const SmTArray<SmLoop*> & rTgtLoops = pCrvClassification->GetTgtLoops() ;
              
              // UVPoint => mapped => back to 3d space
              SmPoint3d  sTestPoint3d ;
              SmVector3d sTestSurfDU, sTestSurfDV ;
              pSurface->Evaluate1stDerivatives(sUV[0], TRUE, TRUE, sTestPoint3d, sTestSurfDU, sTestSurfDV) ;
              SmVector3d sTestTan3d = sUVDir.x * sTestSurfDU + sUVDir.y * sTestSurfDV ;

              // Min Angle Boundary Curve
              SmExtent1d  sMinTrimIvl ;
              double      dUVMinAngleDeg = sAngRangeDeg.GetMin() ;
              SmVector2d  sUVMinDir(smos_CosDeg(dUVMinAngleDeg), smos_SinDeg(dUVMinAngleDeg)) ; 
              sSurfUVDomain.IntersectWithInfiniteLine(sUV[0], sUVMinDir, bFoundInterval, sMinTrimIvl) ;
              SmPoint3d   sMinEndUV      = sUV[0] + sMinTrimIvl.GetMax() * sUVMinDir ; 
              SmCurve   * pUVMinTrimLine = new (rContext) SmLine(sUV[0], sMinEndUV, 2, &rContext) ;
              SmObjDelete sMinClean1(pUVMinTrimLine) ; // deletes previously stored pUVTrimLines
              SmCurve   * pMinCrvOnSurf = new (rContext) SmCrvOnSurf(*pUVMinTrimLine, *pSurface, &sSurfUVDomain, 0, &rContext) ; // 0 = delete nothing when destructed
              SmObjDelete sMinClean2(pMinCrvOnSurf) ; // deletes previously stored pUVTrimLines
              SmVector2d  sMinUVDir(smos_CosDeg(dUVMinAngleDeg), smos_SinDeg(dUVMinAngleDeg)) ;
              SmVector3d  sMinTan3d = sMinUVDir.x * sTestSurfDU + sMinUVDir.y * sTestSurfDV ;

              // max angle boundary curve
              SmExtent1d  sMaxTrimIvl ;
              double      dUVMaxAngleDeg = sAngRangeDeg.GetMax() ;
              SmVector2d  sUVMaxDir(smos_CosDeg(dUVMaxAngleDeg), smos_SinDeg(dUVMaxAngleDeg)) ; 
              sSurfUVDomain.IntersectWithInfiniteLine(sUV[0], sUVMaxDir, bFoundInterval, sMaxTrimIvl) ;
              SmPoint3d   sMaxEndUV      = sUV[0] + sMaxTrimIvl.GetMax() * sUVMaxDir ; 
              SmCurve   * pUVMaxTrimLine = new (rContext) SmLine(sUV[0], sMaxEndUV, 2, &rContext) ;
              SmObjDelete sMaxClean1(pUVMaxTrimLine) ; // deletes previously stored pUVTrimLines
              SmCurve   * pMaxCrvOnSurf = new (rContext) SmCrvOnSurf(*pUVMaxTrimLine, *pSurface, &sSurfUVDomain, 0, &rContext) ; // 0 = delete nothing when destructed
              SmObjDelete sMaxClean2(pMaxCrvOnSurf) ; // deletes previously stored pUVTrimLines
              SmVector2d  sMaxUVDir(smos_CosDeg(dUVMaxAngleDeg), smos_SinDeg(dUVMaxAngleDeg)) ;
              SmVector3d  sMaxTan3d = sMaxUVDir.x * sTestSurfDU + sMaxUVDir.y * sTestSurfDV ;

              smgfx_Erase() ;
              smgfx_SetLook(1,2, 0,0,1) ; if(pBrep) pBrep->Draw(TRUE) ; sm_GraphicsLoop() ;
              smgfx_SetLook(3,4, 1,0,0) ; if(pEdge) pEdge->Draw() ; sm_GraphicsLoop() ;
              smgfx_SetLook(5,6, 1,0,1) ; sPN[0].Draw() ; sm_GraphicsLoop() ;

              smgfx_SetLook(2,3, 1,0,0) ; if(pMinCrvOnSurf) pMinCrvOnSurf->Draw() ; sm_GraphicsLoop() ;
              smgfx_SetLook(8,9, 1,0,0) ; sMinTan3d.Draw(&sTestPoint3d) ; sm_GraphicsLoop() ;

              smgfx_SetLook(3,4, 1,0,0) ; if(pCrvOnSurf) pCrvOnSurf->DrawParams() ; sm_GraphicsLoop() ;
              smgfx_SetLook(8,9, 0,1,0) ; sTestTan3d.Draw(&sTestPoint3d) ; sm_GraphicsLoop() ;

              smgfx_SetLook(2,3, 0,0,1) ; if(pMaxCrvOnSurf) pMaxCrvOnSurf->Draw() ; sm_GraphicsLoop() ;
              smgfx_SetLook(8,9, 0,0,1) ; sMaxTan3d.Draw(&sTestPoint3d) ; sm_GraphicsLoop() ;
              pFaceProps->Draw(TRUE) ; sm_GraphicsLoop() ; // sSheetColor         - def:[ 0, 1, 1]
                                                           // sCrossedSeamColor   - def:[ 1, 0, 1]
                                                           // sMissingSeamColor   - def:[ 1, 0, 0]
                                                           // sMissingPoleColor   - def:[ 0, 0, 1]
                                                           // sBadOrientLoopColor - def:[.3,.3,.3]
                                                           // sNoArea_LoopColor   - def:[ 0, 0, 0]
              smgfx_SetLook(2,3, 1,0,0) ; if(rLoops[lTgtLoopIndx]) rLoops[lTgtLoopIndx]->Draw() ; sm_GraphicsLoop() ; 
              smgfx_SetLook(4,5, 0,1,1) ; for(di=0;di<rTgtLoops.GetSize();di++)
                                            { if(rTgtLoops[di]) rTgtLoops[di]->Draw() ; sm_GraphicsLoop() ; }
              sm_GraphicsLoop() ;
            }
#endif // SM_DEBUG_CODE

          // Classify the sCrvOnSurf against this Loop and all unmarked loops only
          pFace->CurveOnClassify(TRUE,               // in : TRUE =Do expensive PtClassification for Curves not XSecting any Face->Bndrys 
                                                     //    : FALSE=classify such points as unknown. (good when Curve is known to be InFace) 
                                *pCrvClassification, // i/o: contains m_cpCurve to classify, accumulates ivls as they are found. 
                                 TRUE,               // in : TRUE = m_cpCurve and Face->Edges connect to Face where Edge/Face gaps are suspected to exceed XSectTol3d. 
                                                     //    :      increase XSectTol3d to accomodate large Edge/Face gaps 
                                                     //    :      (more expensive option - computes Face/Surface gaps) 
                                                     //    : FALSE= Expect all Face/Edge gaps to be within XSectTol3d, use standard SmTol::GetXSectTol3d tols. 
                                                     //    : default:[FALSE] 
                                 TRUE,               // in : TRUE = When finding XSectPoints, also check 3d dists 
                                                     //    : FALSE= When finding XSectPoints, only check 2d dists for XSects 
                                                     //    : default:[FALSE] 
                                 &bModifiedCurve,    // out: TRUE  = m_cpCurve modified to tighten tols 
                                                     //    : FALSE = m_cpCurve not modified 
                                                     //    : When m_cpCurve is modified, the classification is cleared and 
                                                     //    : rebuilt from scratch - if accumulating classifications from   
                                                     //    : a sequence of calls, start over. Call CrvClassif->ReSet() and restart sequence. 
                                                     //    : If this is the only classification call, then CrvClassif is complete 
                                                     //    : and may be used as returned. 
                                                     //    : NULL to ignore, default:[NULL] 
                                  bUVSpaceOkay       // in : TRUE = okay to try UVSpace Classification if 3Space classification is dodgey (tolerant cases) 
                                                     //    : FALSE= don't use UVSpace because UVTrimCurves are not known to be valid, default:[TRUE] 
                                 ) ;

          // get the classification curve vertex intersections
          SmTArray<SmVertex *> sVertices ;
          pCrvClassification->FindVertexObjects(sVertices) ;
          SmTArray<SmEdge *> sCoinEdges ;
          pCrvClassification->FindEdgeObjects(sCoinEdges, NULL, 1) ; // 1 = get CoincidentEdges only

          SmZoneTol3d sZoneTol3d = SmTol::GetZoneTol3d(pFace) ; 
          SmZoneTol3d sZoneTol3dSq = sZoneTol3d * sZoneTol3d ; 

#ifdef SM_DEBUG_CODE
          if(bDebugMe)
            {
              pFaceProps->Dump() ; 
              pCrvClassification->Dump() ;

              ULONG di ; 
              SmBrep                  * pBrep     = pFace ? pFace->GetBrep() : NULL ; 
              const SmTArray<SmLoop*> & rTgtLoops = pCrvClassification->GetTgtLoops() ;

              smgfx_Erase() ;
              smgfx_SetLook(1,2, 0,0,1) ; if(pBrep) pBrep->Draw(TRUE) ; sm_GraphicsLoop() ;
              pFaceProps->Draw(TRUE) ; sm_GraphicsLoop() ; // sSheetColor         - def:[ 0, 1, 1]
                                                           // sCrossedSeamColor   - def:[ 1, 0, 1]
                                                           // sMissingSeamColor   - def:[ 1, 0, 0]
                                                           // sMissingPoleColor   - def:[ 0, 0, 1]
                                                           // sBadOrientLoopColor - def:[.3,.3,.3]
                                                           // sNoArea_LoopColor   - def:[ 0, 0, 0]
              smgfx_SetLook(2,3, 1,0,0) ; if(rLoops[lTgtLoopIndx]) rLoops[lTgtLoopIndx]->Draw() ; sm_GraphicsLoop() ; 
              smgfx_SetLook(3,4, 1,0,0) ; if(pCrvOnSurf) pCrvOnSurf->DrawParams() ; sm_GraphicsLoop() ;
              smgfx_SetLook(3,4, 1,0,0) ; if(pCrvClassification) pCrvClassification->Draw(FALSE) ; sm_GraphicsLoop() ;
              smgfx_SetLook(4,5, 0,1,1) ; for(di=0;di<rTgtLoops.GetSize();di++)
                                            { if(rTgtLoops[di]) rTgtLoops[di]->Draw() ; sm_GraphicsLoop() ; }
              sm_GraphicsLoop() ;
            }
#endif // SM_DEBUG_CODE

          // When the pCrvClassification is far from any tolerance problems - use it to classify the loop
          //   far from tol problems when:
          //      no Coincident Edge classifications
          //      no Vertex classifications
          //      or just one vertex classification on a singularity
          if(   (sCoinEdges.GetSize() == 0)
             && (   (sVertices.GetSize() == 0)
                 || (   pFaceProps->m_lPoles != SM_SS_NONE 
                     && sVertices.GetSize() == 1
                     && (   ((pFaceProps->m_lPoles & SM_SS_UMIN) && (sZoneTol3dSq.val > (pFaceProps->m_sPolePoints[0]-sVertices[0]->GetPoint()).LengthSquared()))
                         || ((pFaceProps->m_lPoles & SM_SS_VMIN) && (sZoneTol3dSq.val > (pFaceProps->m_sPolePoints[1]-sVertices[0]->GetPoint()).LengthSquared()))
                         || ((pFaceProps->m_lPoles & SM_SS_UMAX) && (sZoneTol3dSq.val > (pFaceProps->m_sPolePoints[2]-sVertices[0]->GetPoint()).LengthSquared()))
                         || ((pFaceProps->m_lPoles & SM_SS_VMAX) && (sZoneTol3dSq.val > (pFaceProps->m_sPolePoints[3]-sVertices[0]->GetPoint()).LengthSquared()))
                        ) // end and lone vertex is on Pole
                    ) // end or There are singularities and there is just one vertex and lone vertex is on pole
                 ) // end NoVertices or 1 Vertex on Pole
             ) // end no CoinEdges and (NoVertices or 1 Vertex on Pole)
            {
              bFound = TRUE ;
              break ;
            }
        
        } // end iter jj, trial ClassifyCurves

    // other output - rebCLassifyCrv_Closed3d
    SmExtent1d sIvl = pCrvOnSurf->GetNaturalInterval() ; 
    SmPoint3d sStartPt, sEndPt ;
    pCrvOnSurf->EvaluatePoint(sIvl.GetMin(), sStartPt) ;
    pCrvOnSurf->EvaluatePoint(sIvl.GetMax(), sEndPt) ;

    // ClassifyCrv is closed when EndPt_Gap is degenerate
    rebCLassifyCrv_Closed3d = SmTol::IsDegenerate(sEndPt-sStartPt) ; 
    
    // arrive here when bFound == FALSE - did not find a good ClassifyCurve (need to use an okay one)
    //                bFound == TRUE  - found a tolerance free clean classification 
    if(bFound == TRUE)
      {
        // use this classification in the next section
        break ;
      }
  } // end iter ii, every Loop->edge looking for a good UVTrimCurve Loop bisector

#ifdef SM_DEBUG_CODE
  if(bDebugMe)
    {
      SM_ASSERT_MSG(bFound == TRUE,
                    _T("SmFace::ClassifyLoops->sms_FindAndClassifyLoopBisector - CrvClassify not found - algorithm extension needed")) ;
      SM_ASSERT_MSG(pCrvClassification->GetSize() >= 1,
                    _T("SmFace::ClassifyLoops->sms_FindAndClassifyLoopBisector - expect CurveClasssify to have at least one interval - debug needed")) ;
      SM_DUMP_AND_ASSERT_VALID(pCrvClassification) ;
    }
#endif // SM_DEBUG_CODE

  // make the output curves permanent and owned by pCrvClassification - these will be deleted when pCrvClassification is deleted
  sCleanCrvOnSurf.Clear() ;                      // stop deletion of pCrvOnSurf on Exit
  sCleanUVTrimLine.Clear() ;                     // stop deletion of pUVTrimLine on Exit

  // set remiaining output
  rpCrvOnSurf  = pCrvOnSurf  ; 
  rpUVTrimLine = pUVTrimLine ;

  // pCrvOnSurf->SetOwnerFlag(1) ;                  // 1    = pCrvOnSurf owns pUVTrimLine stored in m_pUVCurve which is deleted when destructed
  // pCrvClassification->SetIsCurveOwned( TRUE ) ;  // TRUE = pCrvClassification owns pCrvOnSurf in m_cpCurve which is deleted when destructed

  // all done 
  return( SM_SUCCESS ) ;

} // end sms_FindAndClassifyLoopBisector

/*******************************************************************//**
PURPOSE: Find and Fix False Internal Point Classifications where
         a curve classification and edge intersect without crossing

NOTES: This function is needed because PointClassifications indicate
    an intersection, not a crossing. But crossing is what we need.

METHOD: Take a small step on the loop curve(s) in both directions away from
    the intersection. Drop the two points to the surface to get the UV
    points. Analyze the UV points to see if they are on opposite sides of
    the UVDomain-bisecting UVTrimLine.
***********************************************************************/
SmStatus sms_ReviewTangentCrvClassifies
( SmCurveClassification & rCrvClassification,    // in : Tgt CrvClassification
  SmCurve               & rUVTrimLine,           // in : UVTrimLine associated with ClassifyCrv
  SmSurface             * pSurface,              // in : Surface that the UVTrimLine lives on
  SmFaceProps           & rFaceProps,            // in : only used for rFaceProps.m_pFace
  ULONG                 & lFalseEdgeClassifyCnt  // out: number of PtClassify Edge to UNKNOWN changes made to CrvClassification
)
{
  // Locals
  ULONG      lSize          = rCrvClassification.GetSize();
  SmLine   * pUVLine        = SM_CAST_NONNULL_PTR( SmLine, &rUVTrimLine) ; NER_MSG( pUVLine, _T( "UVTrimLine isn't an SmLine. Expected for Vertexuse_TYPE Loops." ) );
  SmVector3d sUVTrimLineVec = pUVLine->GetLineVector();
  SmPoint3d  sUVTrimLinePnt = pUVLine->GetLinePoint();
  SmPoint2d sUVHi, sUVLo;
  SmFace  * pFace           = rFaceProps.m_pFace;
  SmTArray<SmLoop*> sLoops;
  pFace->GetLoops( sLoops );
  ULONG     lNumLoops       = sLoops.GetSize();

  // Init output
  lFalseEdgeClassifyCnt = 0;

  // For every internal point classification look for non-crossing PCs 
  for(ULONG ii=1;ii<lSize;ii++)
    {
      SmPointClassification * pPC     = &( rCrvClassification[ii].m_vStart );
      SmEdge                * pEdge   = pPC->GetEdgeObject();
      SmVertex              * pVertex = pPC->GetVertexObject();

      // no work - no vertex or edge
      if(!pEdge && !pVertex)
        { continue ; }
        
      // Get UV points along the loop in both directions from the PC
      if(pEdge)
        {
          // Loop locals
          SmCurve   * pCurve    = pEdge->GetCurve();
          SmExtent1d  sIvl      = pEdge->GetInterval();
          double      dTParam   = pPC->GetTParam();
          double      dParamTmp = dTParam + sIvl.GetLength() * 0.01;
          double      dParamHi  = sIvl.ClampValue( dParamTmp );
          double      dParamLo  = sIvl.ClampValue( dTParam - sIvl.GetLength() * 0.01 );
          double      dGap;
          SmBoolean   bIsMulti;
          SmBoolean   bSuccess;
          SmPoint3d   sPtHi, sPtLo;

          pCurve->EvaluatePoint( dParamHi, sPtHi );
          pCurve->EvaluatePoint( dParamLo, sPtLo );

          // If the PC is near a seam, this sets the guess on the correct side -> result is on the right side
          if ( dParamHi != dParamTmp )
            {
              pSurface->DropPoint(sPtLo, pSurface->GetNaturalUVDomain(), NULL, bSuccess, sUVLo, dGap, bIsMulti);
                pSurface->DropPoint(sPtHi, pSurface->GetNaturalUVDomain(), &sUVLo, bSuccess, sUVHi, dGap, bIsMulti);
            }
          else
            {
              pSurface->DropPoint(sPtHi, pSurface->GetNaturalUVDomain(), NULL, bSuccess, sUVHi, dGap, bIsMulti);
                pSurface->DropPoint(sPtLo, pSurface->GetNaturalUVDomain(), &sUVHi, bSuccess, sUVLo, dGap, bIsMulti);
            }

        } // end classifyObj == Edge branch
      else // ClassifyObj == Vertex branch
        {
          // Skip testing vertices on seams
          if(pVertex->IsOnSeam())
            { continue; }

          // Check each loop for connection to this vertex PC
          for(ULONG jj=0;jj<lNumLoops;jj++)
            {
              SmLoop * pLoop = sLoops[jj];

              // no work - Vertex not connected to ThisLoop
              if(!pLoop->IsConnectedTo(pVertex))
                { continue; }

              SmTArray<SmEdge*> sVertexEdges, sLoopEdges;
              pVertex->GetEdges( sVertexEdges ) ;
              pLoop->GetEdges( sLoopEdges ) ;
              sLoopEdges.FindCommonElements( sVertexEdges, sLoopEdges );
              ULONG lNumEdges = sLoopEdges.GetSize();
              SmTArray<SmVertexuse*> sVertexuses, sVertexusesTmp;

              // Get number of vertexuses. Hope for 4. If not... ?
              for(ULONG kk=0;kk<lNumEdges;kk++)
               {
                  pVertex->GetVertexusesOfEdge( sLoopEdges[kk], sVertexusesTmp );
                  sVertexuses.Append( sVertexusesTmp );
               }

              ULONG lNumVertexuses = sVertexuses.GetSize();
              if(lNumVertexuses != 4)
                {
                  SM_DBG_WARN( _T( "sms_ReviewTangentCrvClassifies(): Unexpected number of vertexuses during loop classification. Skipping case." ) );
                  continue;
                }

              SmEdgeuse  * pEdgeuse0 = sVertexuses[0]->GetEdgeuse() ;
              SmEdgeuse  * pEdgeuse2 = sVertexuses[2]->GetEdgeuse() ;
              SmEdge     * pEdge0    = pEdgeuse0->GetEdge() ;
              SmEdge     * pEdge2    = pEdgeuse2->GetEdge() ;
              SmExtent1d   sIvl0     = pEdge0->GetInterval() ;
              SmExtent1d   sIvl2     = pEdge2->GetInterval() ;
              SmPoint3d    sPt0, sPt2 ;
              SmBoolean    bSuccess ;
              double       dGap ;
              SmBoolean bIsMulti;

              double dParam0 = (pEdgeuse0->GetOrientation() == SM_OT_SAME) ? sIvl0.GetMin() + 0.01 * sIvl0.GetLength()
                                                                           : sIvl0.GetMax() - 0.01 * sIvl0.GetLength() ;
              double dParam2 = (pEdgeuse2->GetOrientation() == SM_OT_SAME) ? sIvl2.GetMin() + 0.01 * sIvl2.GetLength()
                                                                           : sIvl2.GetMax() - 0.01 * sIvl2.GetLength() ;

              pEdge0->GetCurve()->EvaluatePoint(dParam0, sPt0) ;
              pEdge2->GetCurve()->EvaluatePoint(dParam2, sPt2) ;

              pSurface->DropPoint(sPt0, pSurface->GetNaturalUVDomain(), NULL, bSuccess, sUVHi, dGap, bIsMulti);
              pSurface->DropPoint(sPt2, pSurface->GetNaturalUVDomain(), &sUVHi, bSuccess, sUVLo, dGap, bIsMulti);

              break; // assumes vertex is connected to only one loop - that's okay a vertex can only be connected to 1 Loop on 1 Face
            } // end for each loop
        } // end ClassifyObj == Vertex branch

      // Now check which side of the bisection UVTrimCurve the UV points are on
      double dMagHi = ( sUVHi.x - sUVTrimLinePnt.x ) / sUVTrimLineVec.x;
      double dMagLo = ( sUVLo.x - sUVTrimLinePnt.x ) / sUVTrimLineVec.x;

      SmBoolean bPtHiAbove = sUVHi.y > (sUVTrimLinePnt.y + dMagHi * sUVTrimLineVec.y) ;
      SmBoolean bPtLoAbove = sUVLo.y > (sUVTrimLinePnt.y + dMagLo * sUVTrimLineVec.y) ;

      // if the UV points are on the same side of the bisector, then remove the non-crossing PC
      if(bPtHiAbove == bPtLoAbove)
        {
          // remove this nonCrossing PtClass from the CurveClassification
          rCrvClassification.RemovePointClass(ii, SM_IP_START) ;

          // adjust iterator values
          ii-- ;
          lSize-- ;

          // count the removal
          lFalseEdgeClassifyCnt++ ;

        } // end UVPts on same side of bisector check
    } // end iter every internal point classification look for non-crossing PCs
        
  // all done
  return SM_SUCCESS;

} // end sms_ReviewTangentCrvClassifies

/*******************************************************************//**
PURPOSE: Find and remove First and Last OnEdge PointClassifies connected to
         ClassifyIntervals that don't enter the face

NOTES: This function is used by the healer's HasSeamProblems to remove
       one-sided classifyCrv edge intersection where the classify
       curve is not entering the face.  That keeps the healer
       from assuming that one sided intersections are a problem
       that needs healing when one sided intersections are just
       fine.
       SMLib doesn't use this feature all the time because one sided
       intersections not entering the face are perfectly valid
       for a boolean in which two parts are just touching at a
       point.  In the booleans vertices are intersected first and
       so this case should not come up but it makes me feel that
       there are probably other cases where the one-sided interesctions
       should still be kept.  So I'm making this a separate method
       rather than integrating it into ClassifyCurveOn().

1. When a Loop contains a SeamEdge and the Edges of the loop
   are classified against a CrvClassification that both starts and 
   stops on a SeamEdge to which it is not coincident the Seam then
   two cases are possible: either
      1. both sides of the SeamEdge are part of the loop, or
      2. just one side of the SeamEdge is part of the loop.

                        ++-----------------------------++
                        ||                             ||-- Periodic Surface
                        ||                             ||
        ClassifyCrv     ##-----------------------------##
        that starts  _  || /  /   /   /   /   /   /   /||- Face on Periodic Surface
        and stops on  \ ||   /   /   /   /   /   /   / ||    The FaceEdge coincident with the  
        a two-sided    -++~~~~~~~~~~~~~~~~~~~~~~~~~~~~~++    Surface Periodic bounday uses
        SeamEdge        || /   /   /   /   /   /   /  /||    both sides of the Seam
                        ||/   /   /   /   /   /   /  / ||      as part of the face boundary.
                        ##-----------------------------##    
                        ||                             ||
                        ||                             ||
        ClassifyCrv     ||                   #---------#|
        that starts  _  || Face on Periodic--|/ / / / /||  note: The FaceEdge coincident with
        and stops on  \ ||    Surface        | / / / / ||        the Surface Periodic boundary
        a one-sided    -|+~~~~~~~~~~~~~~~~~~~+~~~~~~~~~+|        only uses one side of the Seam
        SeamEdge        ||                   | / / / / ||        as part of the face boundary.
                        ||                   #---------#|       
                        ||                             ||
                        ++-----------------------------++    
        
    a case that necessitates verifying each CrvClassification end on its own merits
                        ++-----------------------------++
                        ||   Face on Periodic          ||-- Periodic Surface
                        ||      Surface _              ||
                        ||               \             ||
                        ##-----------------------------##
    ClassifyCrv that    ||/   /   /   /   /   /   /   /||- Face on Periodic Surface
    starts on the unused||   /   /   /   /   /   /   / ||   -The first FaceEdge coincident with the  
    side of a one-sided ||  /   /   /   /   /   /   / ~+|    Surface Periodic bounday uses
    SeamEdge and ends   || /   /   /   /   /   /  ~~~~ ||    both sides of the Seam
    on a two sided      ||/   /   /   /   /   ~~~~/   /||    as part of the face boundary.
    SeamEdge. Edit      |#-----------#   ~~~~/   /   / ##   -The second FaceEdge coincident with the  
    ClassifyCrv Start to||           +~~~   /   /   /  ||    Surface Periodic bounday uses
    classify==UNKNOWN_  ||      ~~~~ | /   /   /   /   ||    one side of the Seam as part
                      \ ||  ~~~~     |/   /   /   /   /||    of the face boundary.
                       -|+~~         |   /   /   /   / ||  
                        ||           #-----------------#|  
                        ||                             ||
                        ++-----------------------------++   


   The SmFace::CurveOnClassify() method at the heart of the previous
   sms_FindAndClassifyLoopBisector() call classifies ClassifyCrvs
   against Edges and not sides of Edges and can't distinguish between
   these two cases.  This SmFace::ClassifyLoops() helper function
   uses the additional information of knowing the sequence of how 
   Edges connect within a Loop to decide if a Seam Edge Side is being used
   in that loop or not.

   Perhaps this extra cleanup is not limited to the ClassifyLoops() call
   and should be made part of the general SmFace::CurveOnClassify() method.
   However, in the healer the ClassifyCrv is known to NOT be coincident
   with a possible SeamEdge.  In general that's not true.

2. The most recent implementation found it was much simpler not to check
   if the CrvClassify EndPts were on seams or not.  All EndPts are
   now treated the same.  When a CrvClassify EndPt classifies to an Edge
   The Edge is examined to find out which UpperEdgeuse direction
   (SM_OT_SAME or SM_OT_OPPOSITE) bounds the ClassifyCrv. 
   When the Edge has a properly oriented Edgeuse that's connected to 
   the CrvClassification's UpperFaceuse then the EndPt is part of the
   Face and remains within the CrvClassification, otherwise the
   EndPt is not part of the Face boundary and its PointType classification
   is changed from SM_PC_EDGE to SM_PC_UNKNOWN.

3. Naming is very confusing in this method because three different
   geometric entities have starts and stops.  SMLib's typical naming
   of Start/End to distinguish between the ends of a Curve is not
   enough by the time we are dealing with the last level of classification
   to keep things (barely) manageable we will use the following words
   to mark object end points:
     ClassifyCrv  :  First/Last  as in ClassifyCrv_FirstPoint and ClassifyCrv_LastPoint
  // no longer in the method:   SeamEdge     :  Start/Stop  as in SeamEdge_StartPoint and SeamEdge_StopPoint
  // no longer in the method:   UVSector Vecs:  Beg/End     as in UVSector_BegVec and UVSector_EndVec
   Apologies in advance, the variable names get a little long trying to make these relationships readable.
***********************************************************************/
SmStatus sms_ReviewStartAndStopOnSeamCrvClassifies
  (SmCurveClassification  & rCrvClassification,    // in : Tgt CrvClassification
   SmCurve                & rUVTrimLine,           // NotUsed: in : UVTrimLine associated with ClassifyCrv
   SmPointClassification *& rpFirstPtClassify,     // out: NotNULL = ClassifyCrv First PtClassify on an EdgeSide part of FaceBndry, NULL = Not on an Edge
   SmPointClassification *& rpLastPtClassify,      // out: NotNULL = ClassifyCrv Last  PtClassify on an EdgeSide part of FaceBndry, NULL = Not on an Edge
   SmEdgeuse             *& rpEdgeFirstSide,       // out: The Edgeuse that bounds the FirstPtClassify when it classifies to an Edge
   SmEdgeuse             *& rpEdgeLastSide,        // out: The Edgeuse that bounds the LastPtClassify  when it classifies to an Edge
   ULONG                  & lFalseEdgeClassifyCnt, // out: number of PtClassify Edge to UNKNOWN changes made to CrvClassification
   SmFaceProps            * pOptFaceProps          // in : OptFaceProps for debug blocks only, NULL to ignore, default:[NULL]
   )    
{
  SM_REF1(rUVTrimLine) ;
  // locals 
  ULONG lSize = rCrvClassification.GetSize() ; 

  // init output
  rpFirstPtClassify     = &(rCrvClassification[0].m_vStart) ;
  rpLastPtClassify      = &(rCrvClassification[lSize-1].m_vEnd) ;
  rpEdgeFirstSide       = rCrvClassification[0]      .GetIvlBound_EdgeuseObj(TRUE,  pOptFaceProps) ; // TRUE = Get MinEndPt Bounding EdgeObj->Edgeuse, pOptFaceProps for DebugBlocks only
  rpEdgeLastSide        = rCrvClassification[lSize-1].GetIvlBound_EdgeuseObj(FALSE, pOptFaceProps) ; // FALSE= Get MaxEndPt Bounding EdgeObj->Edgeuse, pOptFaceProps for DebugBlocks only
  lFalseEdgeClassifyCnt = 0 ;

  // much simpler method originaly implemented here - moved to method SmCurveInterval::GetIvlBound_EdgeuseObj() 

  // when no BndingEdgeuse is found - the ClassifyCrv found an Edge/ClassifyCrv intersection whose
  //      EdgeSide is not being used in this Face 
  //  - Change PtClassification from EDGE to UNKNOWN

  // check 1st ClassifyCrv End for error - classified to an edge but not using that edge side
  if((rpFirstPtClassify->GetPointClass() == SM_PC_EDGE) && (NULL == rpEdgeFirstSide))
    {
      // remove the false CrvClassification EndPt SM_PC_EDGE classification
      rpFirstPtClassify->SetClassObject(SM_PC_UNKNOWN, NULL) ;
      rpFirstPtClassify = NULL ;
      lFalseEdgeClassifyCnt++ ;
    }  // end checking 1st ClassifyCrv End 

  // check last ClassifyCrv End
  if((rpLastPtClassify->GetPointClass() == SM_PC_EDGE) && (NULL == rpEdgeLastSide))
    {
      // remove the false CrvClassification EndPt SM_PC_EDGE classification
      rpLastPtClassify->SetClassObject(SM_PC_UNKNOWN, NULL) ;
      rpLastPtClassify = NULL ;
      lFalseEdgeClassifyCnt++ ; 
    } // end Doing Last ClassifyCrv End branch

  // There are no partner PtClassifies to update because these are the 1st or last CrvPtClassificatons

#ifdef SM_DEBUG_CODE
SmBoolean bDebugMe = FALSE ;
  if(bDebugMe)
    {
      SmBrep * pBrep = pOptFaceProps->m_pFace ? pOptFaceProps->m_pFace->GetBrep() : NULL ; 

      pOptFaceProps->Dump() ;
      rCrvClassification.Dump() ;

      smgfx_Erase() ;
      smgfx_SetLook(1,2, 0,0,1) ; if(pBrep) pBrep->Draw(TRUE) ; sm_GraphicsLoop() ;
      smgfx_SetLook(3,4, 1,0,0) ; rCrvClassification.Draw(FALSE) ; sm_GraphicsLoop() ;  
      smgfx_SetLook(5,6, 1,.5,0) ; if(rpEdgeFirstSide) rpEdgeFirstSide->Draw() ; sm_GraphicsLoop() ;
      smgfx_SetLook(5,6, 1,.75,.8) ; if(rpEdgeLastSide) rpEdgeLastSide->Draw() ; sm_GraphicsLoop() ;
      pOptFaceProps->Draw(TRUE) ; sm_GraphicsLoop() ; // sSheetColor         - def:[ 0, 1, 1]
                                                      // sCrossedSeamColor   - def:[ 1, 0, 1]
                                                      // sMissingSeamColor   - def:[ 1, 0, 0]
                                                      // sMissingPoleColor   - def:[ 0, 0, 1]
                                                      // sBadOrientLoopColor - def:[.3,.3,.3]
                                                      // sNoArea_LoopColor   - def:[ 0, 0, 0]
      sm_GraphicsLoop() ;
    }
#endif // SM_DEBUG_CODE

  // all done
  return(SM_SUCCESS) ;

} // end sms_ReviewStartAndStopOnSeamCrvClassifies

