/*******************************************************************//**
PURPOSE: Compute the total size of the memory used by the SmFace,
            its surface, all its SmFaceuses, loops, and loopuses,
            and their attributes.

NOTES: rtn: smaller size of actually used memory in bytes
***********************************************************************/
ULONG SmFace::GetMemoryUsed
(
  ULONG & rlMemoryAllocated,  // out: bigger size of all allocated memory in bytes
  SmMarkType eMarkType        // in : uses without increment eMarkType value
) const
{
  // in case this method is called directly - get a mark for attribute memory usage
  SmNewMarkAndLock sMarkLock ;
  if(eMarkType == SM_MT_NOMARK)
    {
      eMarkType = sMarkLock.SetContext((SmContext *)GetContext()) ;
    }

  // init output and return
  rlMemoryAllocated = 0 ;
  ULONG lUsed       = 0 ;

  // locals
  ULONG ii, lThisAllocated ;
  SmFaceuse *pFU,   *pOtherFU ;
  SmLoopuse *pLU,   *pOtherLU ;
  SmLoop    *pLoop, *pOtherLoop ;
  SmTArray<SmLoopuse*> sUpwardLoopuses ;

  // connected objects
  this->GetFaceuses(pFU, pOtherFU) ;
  this->GetUpwardLoopuses(sUpwardLoopuses) ;

  // this + attribute memory
  lUsed             +=   sizeof(*this)
                       + this->GetAttributeMemoryUsed(lThisAllocated,
                                                      eMarkType) ;  // note: uses without increment eMarkType value
  rlMemoryAllocated +=   sizeof(*this) + lThisAllocated;

  // upward SmFaceuse + attributes
  lUsed             +=   sizeof(*pFU)
                       + pFU->GetAttributeMemoryUsed(lThisAllocated,
                                                     eMarkType) ;  // note: uses without increment eMarkType value
  rlMemoryAllocated +=   sizeof(*pFU) + lThisAllocated ;

  // other SmFaceuse + attributes
  lUsed             +=   sizeof(*pOtherFU)
                       + pOtherFU->GetAttributeMemoryUsed(lThisAllocated,
                                                          eMarkType) ;  // note: uses without increment eMarkType value
  rlMemoryAllocated +=   sizeof(*pOtherFU) + lThisAllocated ;

  // surface memory
  lUsed             += m_pSurface->GetMemoryUsed(lThisAllocated, eMarkType) ;
  rlMemoryAllocated += lThisAllocated ;
  lUsed             += m_pSurface->GetAttributeMemoryUsed(lThisAllocated,
                                                          eMarkType) ;  // note: uses without increment eMarkType value
  rlMemoryAllocated += lThisAllocated ;

  // for every upward Loopuse - add in object and attribute memory
  for(ii=0;ii<sUpwardLoopuses.GetSize();ii++)
    {
      pLU        = sUpwardLoopuses[ii] ;
      pOtherLU   = pLU->GetOtherLoopuse() ;
      pLoop      = pLU->GetLoop() ;
      pOtherLoop = pOtherLU->GetLoop() ;
      SM_ASSERT(pLoop == pOtherLoop) ;

      // Upward Loopuse + attributes
      lUsed             +=   sizeof(*pLU)
                           + pLU->GetAttributeMemoryUsed(lThisAllocated,
                                                         eMarkType) ;  // note: uses without increment eMarkType value
      rlMemoryAllocated +=   sizeof(*pLU) + lThisAllocated ;

      // Other Loopuse + attributes
      lUsed             +=   sizeof(*pOtherLU)
                           + pOtherLU->GetAttributeMemoryUsed(lThisAllocated,
                                                              eMarkType) ;  // note: uses without increment eMarkType value
      rlMemoryAllocated +=   sizeof(*pOtherLU) + lThisAllocated ;

      // Loop + attribute
      lUsed             +=   sizeof(*pLoop)
                           + pLoop->GetAttributeMemoryUsed(lThisAllocated,
                                                           eMarkType) ;  // note: uses without increment eMarkType value
      rlMemoryAllocated +=   sizeof(*pLoop) + lThisAllocated ;

    } // end iter every upwardLoopuse attached to this face

  // all done
  return(lUsed) ;

} // end SmFace::GetMemoryUsed

#define ASSERT_CASE(a) bCase = (a) ; SM_ASSERT(bCase) ; bRtn &= bCase ;
#define ASSERT_CASE_MSG(a,b) bCase = (a) ; SM_ASSERT_MSG(bCase, b) ; bRtn &= bCase ;

