/*******************************************************************//**
AssertRule Predicate names and return values:
  predicate = SmBoolean sm_AssertTestClassNameRule#() ; Rtn: TRUE=OK,    FALSE=Bad,
***********************************************************************/

/*******************************************************************//**
PURPOSE: AssertTest Rule 39 - Face Loops must not share a Vertex

NOTES:
  predicate = Is every Face Loop built from Vertices that no other Loop of
              the same Face uses.
  action    = None. Two Loops were glued together at a Vertex, or one Loop's
              Vertices were rewired into another.
  rtn: TRUE = okay, FALSE = problem

  Face Loops must be disjoint, so no Vertex may be reached from two of them.
  A Vertex used by two Loops pinches the Face area shut at that point, which
  leaves the Face boundary non-manifold there: walking the boundary through
  that Vertex has two ways to continue instead of one.
  SmBrep::CreateFacesWithCurves() states the same input rule ("does not allow
  for loops to touch or cross each other") and NL_Tessellate.cpp requires
  trimming Loops to be disjoint.

  This is the topological half of the Loop disjointness check and costs only
  a Vertex pointer compare per Loop pair, so it runs at SM_LEVEL_0.
  AssertTest 38 catches the same defect through the UVTrimCurves, but only at
  SM_LEVEL_2 and only when the UVTrimCurves agree with the topology.  A
  Vertex legitimately used twice by one Loop - a slit or a figure-eight
  boundary - is not reported: only Vertices shared across two Loops are.
***********************************************************************/
SmBoolean sm_AssertTestFace39
(
  const SmFace * pFace  // in : Face to check
)
{
  // locals
  ULONG ii, jj;
  SM_PTR_ARRAY(sLoops, SmLoop, 16) ;
  SM_PTR_ARRAY(sVertices1, SmVertex, 16) ;
  SM_PTR_ARRAY(sVertices2, SmVertex, 16) ;
  pFace->GetLoops(sLoops) ;
  ULONG lNumLoops = sLoops.GetSize() ;

  // no work - a Face with fewer than 2 Loops has no Loop pair to share a Vertex
  if(lNumLoops < 2)
    { return(TRUE) ; }

  // for every pair of Face Loops
  for(ii=0;ii<lNumLoops;ii++)
    {
      if(sLoops[ii] == NULL)
        { continue ; }

      sLoops[ii]->GetVertices(sVertices1) ;

      for(jj=ii+1;jj<lNumLoops;jj++)
        {
          if(sLoops[jj] == NULL)
            { continue ; }

          sLoops[jj]->GetVertices(sVertices2) ;

          // any Vertex the two Loops both use connects Loops that must be disjoint
          if(sVertices1.HasCommonElements(sVertices2))
            { return(FALSE) ; }
        } // end iter every later Face->Loop
    } // end iter every Face->Loop

  // arrive here when no Vertex is shared by two Face Loops
  return(TRUE) ;

} // end sm_AssertTestFace39

/*******************************************************************//**
PURPOSE: AssertTest Rule 38 helper - do two Face Loops intersect in UVSpace

NOTES: Every pLoop1 UVTrimCurve is intersected with every pLoop2 UVTrimCurve
       and any solution counts.  Two Loops of one Face may not share a
       Vertex, so a touch at the ends of both UVTrimCurves is as much a
       defect as a transversal crossing and gets no exemption.  Two Loops
       sharing an Edge is reported for the same reason: the shared Edge
       carries shared Vertices.

       Missing UVTrimCurves are built here, the same side effect AssertTest 37
       takes on through SmEdgeuse::NormalizedEvaluate().  Edgeuses whose
       UVTrimCurve will not build are inconclusive, not intersections.
  rtn: TRUE = the two Loops intersect, FALSE = no intersection found
***********************************************************************/
static SmBoolean sm_DoLoopsIntersectInUV
(
  const SmLoop    * cpLoop1,   // in : first Face Loop
  const SmLoop    * cpLoop2,   // in : second Face Loop
  const SmSurface & crSurface  // in : Surface whose UVSpace carries both Loops' UVTrimCurves
)
{
  // locals
  ULONG ii, jj ;
  SM_PTR_ARRAY(sEdgeuses1, SmEdgeuse, 16) ;
  SM_PTR_ARRAY(sEdgeuses2, SmEdgeuse, 16) ;
  cpLoop1->GetEdgeuses(sEdgeuses1) ;
  cpLoop2->GetEdgeuses(sEdgeuses2) ;

  // UVTrimCurves are measured in UVSpace, so the 3d ZoneTol has to be mapped there
  SmZoneTol3d sZoneTol3d = SmTol::GetZoneTol3d(&crSurface);
  SmTol2d sUVTol = SmTol::MapTo2d(sZoneTol3d, crSurface.GetNaturalUVDomain().GetMid(), crSurface);

  // for every Loop1 UVTrimCurve
  for(ii=0;ii<sEdgeuses1.GetSize();ii++)
    {
      SmBSplineCurve *pUVCurve1 = NULL ;
      if(   SM_SUCCESS != sEdgeuses1[ii]->GetOrCreateUVTrimCurve(pUVCurve1)
         || pUVCurve1 == NULL)
        { continue ; } // inconclusive - nothing to intersect

      SmExtent1d sInterval1 = pUVCurve1->GetNaturalInterval() ;

      // for every Loop2 UVTrimCurve
      for(jj=0;jj<sEdgeuses2.GetSize();jj++)
        {
          SmBSplineCurve *pUVCurve2 = NULL ;
          if(   SM_SUCCESS != sEdgeuses2[jj]->GetOrCreateUVTrimCurve(pUVCurve2)
             || pUVCurve2 == NULL)
            { continue ; } // inconclusive - nothing to intersect

          SmExtent1d      sInterval2 = pUVCurve2->GetNaturalInterval() ;
          SmSolutionArray sSolutions ;
          if(SM_SUCCESS != pUVCurve1->GlobalCurveIntersect(sInterval1, *pUVCurve2, sInterval2, sUVTol, sSolutions))
            { continue ; } // inconclusive - the intersector gave up on this pair

          // any solution at all places the two Loops on one another
          if(sSolutions.GetSize() > 0)
            { return(TRUE) ; }
        } // end iter every Loop2->Edgeuse
    } // end iter every Loop1->Edgeuse

  // arrive here when no intersection was found
  return(FALSE) ;

} // end sm_DoLoopsIntersectInUV

/*******************************************************************//**
PURPOSE: AssertTest Rule 38 - Face Loops must not intersect one another

NOTES:
  predicate = Do all pairs of Face Loops stay clear of one another in the
              Face's UV space.
  action    = None. The Loop belongs to a different Face, or its
              UVTrimCurves disagree with its Edge Curves.
  rtn: TRUE = okay, FALSE = problem

  Face Loops must be disjoint.  Two Loops of one Face may not share a
  Vertex, so any UVSpace contact is a defect: a transversal crossing, a
  touch at one shared Vertex, and a shared Edge are all reported.
  SmBrep::CreateFacesWithCurves() states the same input rule ("does not
  allow for loops to touch or cross each other"), NL_Tessellate.cpp
  requires trimming Loops to be disjoint, and
  SmTess::CheckPolygonIntersections() enforces it on the tessellated
  polygons.

  This is the SM_LEVEL_2 half of the Loop nesting check.  AssertTest 37
  classifies one sampled UV point per InnerLoop at SM_LEVEL_0, so a Loop
  running from inside the OuterLoop to outside it slips past whenever the
  sampled point lands on the inside stretch.  Intersecting the UVTrimCurves
  pairwise catches those Loops, at the cost of an Edgeuse x Edgeuse
  curve/curve intersection sweep per Loop pair, so it is reserved for
  SM_LEVEL_2.

  Edgeuses whose UVTrimCurve will not build are inconclusive and are not
  reported as failures.
***********************************************************************/
SmBoolean sm_AssertTestFace38
(
  const SmFace    * pFace      // in : Face to check
)
{
  // locals
  ULONG ii, jj ;
  SM_PTR_ARRAY(sLoops, SmLoop, 16) ;
  pFace->GetLoops(sLoops) ;
  ULONG lNumLoops = sLoops.GetSize() ;
  const SmSurface & crSurface = *pFace->GetSurface() ;

  // no work - a Face with fewer than 2 Loops has no Loop pair to intersect
  if(lNumLoops < 2)
    { return(TRUE) ; }

  // for every pair of Face Loops
  for(ii=0;ii<lNumLoops;ii++)
    {
      if(sLoops[ii] == NULL)
        { continue ; }

      for(jj=ii+1;jj<lNumLoops;jj++)
        {
          if(sLoops[jj] == NULL)
            { continue ; }

          if(TRUE == sm_DoLoopsIntersectInUV(sLoops[ii], sLoops[jj], crSurface))
            { return(FALSE) ; }
        } // end iter every later Face->Loop
    } // end iter every Face->Loop

  // arrive here when no two Face Loops intersect
  return(TRUE) ;

} // end sm_AssertTestFace38

/*******************************************************************//**
PURPOSE: AssertTest Rule 37 helper - sample a UV point on a Loop

NOTES: Edgeuse midpoints are sampled rather than Edgeuse ends because an
       Edgeuse end is a Loop Vertex, and a Vertex is where the sampled Loop
       is most likely to coincide with other topology - a pole or a seam
       Vertex.  Those give SM_POC_ON_BOUNDARY answers that say nothing about
       nesting.  A midpoint is a generic point on the Loop boundary.
  rtn: TRUE = rUVPoint was set, FALSE = no UVTrimCurve could be evaluated
***********************************************************************/
static SmBoolean sm_GetLoopSampleUVPoint
(
  const SmLoop * pLoop,     // in : Loop to sample
  SmPoint2d    & rUVPoint   // out: sampled UV point, only set when rtn is TRUE
)
{
  ULONG ii ;
  SM_PTR_ARRAY(sEdgeuses, SmEdgeuse, 16) ;
  pLoop->GetEdgeuses(sEdgeuses) ;

  for(ii=0;ii<sEdgeuses.GetSize();ii++)
    {
      SmPoint3d sUV ;
      if(SM_SUCCESS == sEdgeuses[ii]->NormalizedEvaluate(0.5, TRUE, sUV))
        {
          rUVPoint.x = sUV.x ;
          rUVPoint.y = sUV.y ;
          return(TRUE) ;
        }
    } // end iter every Loop->Edgeuse

  // arrive here for VertexLoops and Loops with no usable UVTrimCurve
  return(FALSE) ;

} // end sm_GetLoopSampleUVPoint

/*******************************************************************//**
PURPOSE: AssertTest Rule 37 - Face Loops must be properly nested

NOTES:
  predicate = Does every Face InnerLoop lie inside the Face OuterLoop and
              outside every other InnerLoop in the Face's UV space.
  action    = None. The InnerLoop belongs to a different Face, or the
              OuterLoop is misidentified.
  rtn: TRUE = okay, FALSE = problem

  A Face trimmed by an OuterLoop plus one or more InnerLoops only encloses
  an area when each InnerLoop hole sits inside the OuterLoop and the holes
  do not contain one another.  SmTess::CheckPolygonNesting() enforces the
  same rule on the tessellated polygons and fails the whole Face when it
  cannot repair the nesting, so catching it here names the offending Face
  instead of surfacing as a tessellation error.

  This is the SM_LEVEL_0 half of the Loop nesting check.  One sampled UV
  point per InnerLoop is cheap but blind to a Loop that runs from inside
  the OuterLoop to outside it whenever the sample lands on the inside
  stretch.  AssertTest 38 intersects the Loop UVTrimCurves at SM_LEVEL_2
  to catch those.

  SM_POC_UNKNOWN is inconclusive and is not reported as a failure.
***********************************************************************/
SmBoolean sm_AssertTestFace37( const SmFace* pFace )
{
  // locals
  ULONG ii, jj ;
  SM_PTR_ARRAY(sLoops, SmLoop, 16) ;
  pFace->GetLoops(sLoops) ;
  ULONG lNumLoops = sLoops.GetSize() ;

  // no work - a Face with fewer than 2 Loops has no nesting to check
  if(lNumLoops < 2)
    { return(TRUE) ; }

  SmLoop *pOuterLoop = sLoops[0]; // the OuterLoop is the first Loop in the Faceuse Loopuse list
  // inconclusive - a Face with no OuterLoop is reported by another AssertTest
  if(pOuterLoop == NULL)
    { return(TRUE) ; }

  SmZoneTol3d sZoneTol3d = SmTol::GetZoneTol3d(pFace);

  // for every InnerLoop
  for(ii=1;ii<lNumLoops;ii++)
    {
      SmLoop *pInnerLoop = sLoops[ii] ;
      if(pInnerLoop == NULL )
        { continue ; }

      SmPoint2d sSampleUV ;
      if(FALSE == sm_GetLoopSampleUVPoint(pInnerLoop, sSampleUV))
        { continue ; } // inconclusive - nothing to classify

      SmTol2d sUVTol = SmTol::MapTo2d(sZoneTol3d, sSampleUV, *pFace->GetSurface());
      SmEdge       *pOnEdge      = NULL ;
      double        dEdgeParam   = 0.0 ;
      SmOrientType  eOrientation = SM_OT_UNKNOWN ;

      // every InnerLoop must lie inside the OuterLoop
      SmPointObjectContainmentType eContainment = pOuterLoop->ContainsUVPoint(sSampleUV, sUVTol, pOnEdge, dEdgeParam, eOrientation);
      if (eContainment == SM_POC_OUTSIDE || eContainment == SM_POC_ON_BOUNDARY)
        { return(FALSE) ; }

      // no InnerLoop may lie inside another InnerLoop
      for(jj=1;jj<lNumLoops;jj++)
        {
          if(sLoops[jj] == NULL || jj == ii)
            { continue ; }

          if(SM_POC_INSIDE == sLoops[jj]->ContainsUVPoint(sSampleUV, sUVTol, pOnEdge, dEdgeParam, eOrientation))
            { return(FALSE) ; }
        } // end iter every other Face->InnerLoop
    } // end iter every Face->InnerLoop

  // arrive here when all InnerLoops are properly nested
  return(TRUE) ;

} // end sm_AssertTestFace37

/*******************************************************************//**
PURPOSE: AssertTest Rule 34 - Face can not have partially coincident edges
NOTES:
  predicate = Does the face contain partially coincident edges
  action    = None. Consider merging
  rtn: TRUE = okay, FALSE = problem
***********************************************************************/
SmBoolean sm_AssertTestFace34( const SmFace* pFace )
{
    SmBoolean bRtn = TRUE;
    ULONG ii, jj, kk;

    SmTArray<SmEdge*> sEdges;
    pFace->GetEdges( sEdges );

    // Compare each edge with all others
    for ( ii = 0; ii < sEdges.GetSize(); ii++ )
    {
        SmEdge    *pE1 = sEdges[ii];
        SmCurve   *pC1 = pE1->GetCurve();
        SmExtent1d sI1 = pE1->GetInterval();
        SmZoneTol3d dT1 = SmTol::GetZoneTol3d( pE1 );

        for ( jj = ii+1; jj < sEdges.GetSize(); jj++ )
        {
            SmEdge     *pE2 = sEdges[jj];
            SmCurve    *pC2 = pE2->GetCurve();
            SmExtent1d  sI2 = pE2->GetInterval();
            SmZoneTol3d dT2 = SmTol::GetZoneTol3d( pE2 );
            SmZoneTol3d dT  = smos_Max( dT1, dT2 );
            SmBoolean   bMoreWork = FALSE;
            SmSolutionArray sSols;

            pC1->GlobalCoincidenceChecker( sI1, *pC2, sI2, dT, bMoreWork, sSols );

            // Check solutions for range intersections
            for (kk = 0; kk < sSols.GetSize(); kk++ )
            {
                if ( sSols[kk].m_eSolutionType == SM_ST_RANGE_OF_VALUES )
                {
                    bRtn = FALSE;
                    return bRtn;
                }
            } // end for each solution
        } // end for other edge
    } // end for this edge

    return( bRtn ) ;

}
/*******************************************************************//**
PURPOSE: AssertTest Rule 33 - Face can not have coincident edges
NOTES:
  predicate = Does the face contain coincident edges
  action    = Combine topology of two edges close enough to be one: delete one, save the other
              by calling SmBrep::GlueEdges on
              every pair of [pToSurviveEdges[i], pToDeleteEdges[i]].
  rtn: TRUE = okay, FALSE = problem
***********************************************************************/
SmBoolean sm_AssertTestFace33                      
(
  const SmFace          * pFace,                   // in : Face to test
  SmTArray<SmEdge *>    * pOptToSurviveEdges=NULL, // out: List of Edges with coincident partners, NULL to ignore, default:[NULL]
  SmTArray<SmEdge *>    * pOptToDeleteEdges=NULL,  // out: associated coincident partner, NULL to ignore, default:[NULL]
  SmTArray<SmVertex *>  * pOptToSurviveVerts=NULL, // out: Opt HasCoincidentVertices() output, List of Verts with coincident partners, NULL to ignore, default:[NULL]
  SmTArray<SmVertex *>  * pOptToDeleteVerts=NULL   // out: Opt HasCoincidentVertices() output, associated coincident partner, NULL to ignore, default:[NULL]
)
{
  // Test = TRUE when Face Edges are coincident to tol - also finds coincident vertices
  SmBoolean bRtn = !pFace->HasCoincidentEdges(pOptToSurviveEdges, pOptToDeleteEdges, pOptToSurviveVerts, pOptToDeleteVerts) ;

  // all done
  return( bRtn ) ;

} // end sm_AssertTestFace33

