/*******************************************************************//**
PURPOSE: AssertTest Rule 32 - Face can not have coincident vertices
NOTES:
  predicate = Does the face contain coincident vertices 
  action    = Combine topology of two vertices close enough to be one: delete one, save the other
              by calling SmBrep::GlueVertices() on every coincident pair not connected by an edge and
              SmBrep::SqueezeEdge() for every coincident pair connected by an edge
  rtn: TRUE = okay, FALSE = problem
***********************************************************************/
SmBoolean sm_AssertTestFace32                      
(
  const SmFace          * pFace,                   // in : Face to test
  SmTArray<SmVertex *>  * pOptToSurviveVerts=NULL, // out: List of Verts with coincident partners, NULL to ignore, default:[NULL]
  SmTArray<SmVertex *>  * pOptToDeleteVerts=NULL   // out: associated coincident partner, NULL to ignore, default:[NULL]
)
{
  // Test = TRUE when pFace vertices are coincident to within tol
  SmBoolean bRtn = !pFace->HasCoincidentVertices(pOptToSurviveVerts, pOptToDeleteVerts) ;

  // all done
  return( bRtn ) ;

} // end sm_AssertTestFace32

