/*******************************************************************//**
PURPOSE  : SmFace AssertRule 30 -
  Face's stored ZoneTol must equal SmTol::GetZoneTol3d() Consistent Tolerance Model value

  predicate = if(SM_USE_NEWTOL) return TRUE
              else return SM_ARE_SAME(m_sZoneTol3d, SmTol::GetZoneTol3d(this))

  action    = if(SM_USE_NEWTOL) no action
              else if m_sZoneTol3d not equal SmTol::GetZoneTol3d(this)
                      set m_sZoneTol3d = SmTol::GetZoneTol3d(this)
  rtn: TRUE = okay, FALSE = problem
***********************************************************************/
SmBoolean sm_AssertTestFace30        
(
  const SmFace * pFace,             // in : test target
  SmZoneTol3d  * pOptZoneTol3d=NULL // out: opt SmTol::GetZoneTol3d(pFace) value, NULL to ignore
)
{
  SmBoolean bRtn = ((SmFace*)pFace)->IsZoneTol3dConsistent(pOptZoneTol3d) ;

  return( bRtn ) ;

} // end sm_AssertTestFace30

