/*******************************************************************//**
PURPOSE:

RETURNS ---  TRUE  = OK
             FALSE = Problem
***********************************************************************/
SmBoolean SmFace::AssertValid
(
  SmAssertArray    * pAList,        // i/o: Accumulating list of failed Asserts, NULL to ignore, default:[NULL]
  SmAssertTestLevel  eTestLevel,    // in : SM_LEVEL_0=fewest tests, SM_LEVEL_1, SM_LEVEL_2=all tests,
                                    //      SM_LEVEL_GIVEN = run tests in order requested in pTestRequests
                                    //      default:[SM_LEVEL_0]
  SmAssertWalking    eWalkTree,     // in : SM_WALK = run AssertValid on any topology graph descendants, SM_NO_WALK=don't, default:[SM_WALK]
  SmTArray<ULONG>  * pTestRequests  // in : when eTestLevel == SM_LEVEL_GIVEN, run these tests in this order, default:[NULL]
) const
{
  // init rtn value
  SmBoolean bRtn  = TRUE;

#ifdef SM_DEBUG_CODE
SmBoolean bDebugMe = FALSE;
#endif // SM_DEBUG_CODE

  // call the base class AssertValid
  bRtn &= (  (eTestLevel != SM_LEVEL_GIVEN)
           ? SmTopology::AssertValid(pAList, eTestLevel, SM_NO_WALK, pTestRequests)
           : TRUE ) ;

  // locals
  SmZoneTol3d sFaceZoneTol3d = SmTol::GetZoneTol3d(this) ;

// Remove Composites
// // classify the face - SmCFaces are treated differently than SmFaces
//  SmBoolean bIsThisCFace = this->IsKindOf(SmCFace_TYPE) ;
//
//  // Face and the objects it attaches to need to share common contexts
//  if(!bIsThisCFace)
    {
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(0, SM_LEVEL_0, (GetContext() == m_pFU->GetContext()), _T("") ) ;
    }

  if(m_pSurface)
    {
      bRtn &= SM_ASSERT_BOOLEAN_REPORT( 1, SM_LEVEL_0, (GetContext() == m_pSurface->GetContext()), _T("") ) ;
      bRtn &= SM_ASSERT_VALUE_REPORT  ( 2, SM_LEVEL_0, (m_vUVDomain.IsContainedBy(m_pSurface->GetNaturalUVDomain(), SM_EFF_ZERO)), SM_EFF_ZERO, SM_UNDEF_DOUBLE, _T("")) ;
      bRtn &= SM_ASSERT_VALUE_REPORT  (22, SM_LEVEL_0, (m_vUVDomain.XLength() > SM_EFF_ZERO && m_vUVDomain.YLength() > SM_EFF_ZERO), SM_EFF_ZERO, SM_UNDEF_DOUBLE, _T("")) ;
    }

#ifndef SM_DEBUG_CODE
  // note some functions: SmCurveClassification::IntersectEdges(),
  //                    SmCurveClassification::IntersectVertices(), and
  //                    SmSurfaceIntersector::FindBoundaryStartPoints()
  // temporarily clear surface->Owner pointer to prevent building trimSrfCache for crSurface
  // If this check is run from within that temp state - this will be a false error

  // skip this check in Debug mode when m_pSurface is NULL assuming it's been temporarily cleared
  // check 1: Face->Surface pointer is not NULL
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(3, SM_LEVEL_0, (m_pSurface != NULL), _T("") ) ;
#endif // SM_DEBUG_CODE

  // check 1: Face<->Surface back pointers
  if(   m_pSurface && m_pSurface->GetFace() 
     && (   SM_ASSERT_TEST_NEED( 4, SM_LEVEL_0)
         || SM_ASSERT_TEST_NEED( 5, SM_LEVEL_0)
         || SM_ASSERT_TEST_NEED( 6, SM_LEVEL_0)
         || SM_ASSERT_TEST_NEED(23, SM_LEVEL_0)
         || SM_ASSERT_TEST_NEED(24, SM_LEVEL_0)))
    {
      SmFace *pSurfaceFace = (SmFace *)m_pSurface->GetFace() ;
      SmZoneTol3d sSurfaceFaceZoneTol3d = SmTol::GetZoneTol3d(pSurfaceFace) ;

// Remove Composites
//      // When FaceType == SmCFace, Face->Surface->Face must be this Face
//      bRtn &= SM_ASSERT_BOOLEAN_REPORT(4, SM_LEVEL_0, (bIsThisCFace == FALSE || pSurfaceFace == this), _T("")) ;
      // Face->Surface->Face must be this Face
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(4, SM_LEVEL_0, pSurfaceFace == this, _T("")) ;

// Remove Composites
//      // When Surface->Face is composite, this face must be the CFace or one its members
//      SmBoolean bIsSurfaceOwnerCFace = pSurfaceFace->IsKindOf(SmCFace_TYPE) ;
//      bRtn &= SM_ASSERT_BOOLEAN_REPORT(5, SM_LEVEL_0, (   bIsSurfaceOwnerCFace == FALSE
//                                                     || (bIsThisCFace == TRUE  && pSurfaceFace == this)
//                                                     || (bIsThisCFace == FALSE && ((SmCFace *)pSurfaceFace)->ContainsFace(this))), 
//                                                    _T("")) ;

// Remove Composites
//      // When Surface->Face is not composite, the SurfaceFace must be this face
//      bRtn &= SM_ASSERT_BOOLEAN_REPORT(6, SM_LEVEL_0, (   bIsSurfaceOwnerCFace == TRUE
//                                                     || pSurfaceFace == this), 
//                                                    _T("")) ;

      // The face UVDomain must be contained within the Surface domain
      SmExtent2d sSurfaceUV = m_pSurface->GetNaturalUVDomain() ;
      bRtn &= SM_ASSERT_VALUE_REPORT  (23, SM_LEVEL_0, (m_vUVDomain.IsContainedBy(sSurfaceUV, SM_EFF_ZERO)), 0.0, SM_UNDEF_DOUBLE, _T("")) ;

      // Get Face->Surface->Poles (if any)
      SmPoint3d sPoleData[4] ;
      SmTArray<SmPoint3d> sPolePoints(4,sPoleData) ;
      ULONG lPoles = m_pSurface->GetSingularities(&sPolePoints) ;

      // When the surface has singularities (poles) - they must be marked by vertices or out of the model
      if(lPoles != SM_SS_NONE)
        {
          ULONG ii ;

          // for every possible pole:[UMinPole, VMinPole, UMaxPole, VMaxPole]
          for(ii=0;ii<4;ii++)
            {
              // when point is a pole
              if(!sPolePoints[ii].IsUndef())
                {
                  // classify the point against the Face->Brep
                  SmBoolean bDoBoundaryIntersections = TRUE ;
                  SmPointClassification sPointClassification(sSurfaceFaceZoneTol3d, GetContext()) ;  // should be sPolePoints ZoneTol3d
                  this->Point3DClassify(sPolePoints[ii], sSurfaceFaceZoneTol3d, bDoBoundaryIntersections, sPointClassification) ;

                   // When Surface has poles they must be marked by vertices or out of the model
                   SmPointClassificationType ePointType = sPointClassification.GetPointClass() ;
                   bRtn &= SM_ASSERT_BOOLEAN_REPORT  (24, SM_LEVEL_0, (ePointType != SM_PC_FACE && ePointType != SM_PC_EDGE), _T("")) ;

#ifdef SM_DEBUG_CODE
                   // draw all target edges, highlight current edge and classification curve
                   if (bDebugMe)
                     {
                       SmBrep *pBrep = GetBrep() ;

                       this->Dump() ;
                       pBrep->Dump() ;

                       smgfx_Erase();
                       smgfx_SetLook(1,3, 0,0,1) ; if(pBrep) { pBrep->Draw(TRUE) ; } sm_GraphicsLoop() ;
                       smgfx_SetLook(1,3, 1,0,1) ; this->DrawUV(); sm_GraphicsLoop() ; // highlight current target
                       smgfx_SetLook(4,5, 1,0,0) ; sPolePoints[ii].Draw() ; sm_GraphicsLoop() ;
                       sm_GraphicsLoop() ;
                     }
#endif // SM_DEBUG_CODE

                } // end test point is a pole check
            } // end iter every possible test point
        } // end pFace->Surface has poles check


#ifdef SM_DEBUG_CODE
      // draw all target edges, highlight current edge and classification curve
      if (bDebugMe)
        {
          SmBrep *pBrep = this->GetBrep() ;

          this->Dump() ;
          pBrep->Dump() ;

          smgfx_Erase();
          smgfx_SetLook(1,3, 0,0,1) ; if(pBrep) { pBrep->Draw(TRUE) ; } sm_GraphicsLoop() ;
          smgfx_SetLook(1,3, 1,0,1) ; this->DrawUV() ; sm_GraphicsLoop() ; // highlight current target
          sm_GraphicsLoop() ;
        }
#endif // SM_DEBUG_CODE

    } // end m_pSurface existence check
  else if(  m_pSurface 
     && (   SM_ASSERT_TEST_NEED( 4, SM_LEVEL_0)
         || SM_ASSERT_TEST_NEED( 5, SM_LEVEL_0)
         || SM_ASSERT_TEST_NEED( 6, SM_LEVEL_0)
         || SM_ASSERT_TEST_NEED(23, SM_LEVEL_0)
         || SM_ASSERT_TEST_NEED(24, SM_LEVEL_0)))
    {
        // The surface used by this face must have an owner
        bRtn &= SM_ASSERT_BOOLEAN_REPORT(35, SM_LEVEL_0, FALSE, _T("")) ;
    }

// Remove Composites
//  // this next section is not for SmCFaces
//  if(   !bIsThisCFace
//     && (   SM_ASSERT_TEST_NEED( 8, SM_LEVEL_0)
  if(   SM_ASSERT_TEST_NEED(12, SM_LEVEL_0)
     || SM_ASSERT_TEST_NEED(13, SM_LEVEL_0))
    {

      // Now do some geometric tests.
      // (Actually, these tests will generally detect topological errors,
      // such as swapped vertices, missing Edgeuses, etc.)
      //
      // Edge vertex count and endpoint gaps (former tests 8-10) live on SmEdge.
      // Vertexuse/faceuse connection (former test 11) lives on SmVertexuse.
      // Paired loopuse order (former tests 14-16, 18) lives on SmLoop.
      // Remaining Face-owned checks: vertices classify onto this face.

      SmTArray<SmVertex*> Verts;
      ULONG               idx;

      // All Face Vertices are inside the Face.

      SmStatus eStat = SM_ERR;

      this->GetVertices( Verts );
      for ( idx = 0; idx < Verts.GetSize(); idx++ )
        {
          SmVertex *pThisVert = Verts[ idx ];

          SmTArray< SmVertexuse* > Vertuses;
          pThisVert->GetVertexuses( Vertuses );
          ULONG lFaceConnections = 0 ;

          for ( ULONG idx3 = 0; idx3 < Vertuses.GetSize(); idx3++ )
            {
              SmVertexuse *pThisVU = Vertuses[ idx3 ];
              SmZoneTol3d sVertexZoneTol3d = SmTol::GetZoneTol3d(pThisVU) ;

              // look for those vertexuses which connect this vertex to the face
              if ((pThisVU->GetFaceuse() != NULL) && (pThisVU->GetFaceuse()->GetFace() == this ))
                {
                  // count the number of times the vertex connects to this face
                  lFaceConnections++ ;

                  // locals
                  SmPointClassification ptClass(sFaceZoneTol3d, GetContext()) ;
                  SmPoint2d uvPt;
                  eStat = pThisVU->ComputeUVPoint( uvPt ); // side effect: build UVTrimCurve - GWC: do we want that in AssertValid?
                  if( eStat == SM_SUCCESS )
                    {
                      this->PointClassify( uvPt,
                                           sVertexZoneTol3d,
                                           TRUE,  // bDoBoundaryIntersections,
                                           TRUE,  // bUseUVClassification,
                                           ptClass );
                    }
                  else
                    {
                      this->Point3DClassify( pThisVert->GetPoint(),
                                             sVertexZoneTol3d,
                                             TRUE, // bDoBoundaryIntersections,
                                             ptClass );
                    }  // end 2d/3d check

                  // Every face->Vertex must classify back to the face
                  bRtn &= SM_ASSERT_BOOLEAN_REPORT(12, SM_LEVEL_0, (ptClass.GetPointClass() != SM_PC_UNKNOWN), _T("")) ;

                  break; // need to check only one VU of each Vertex that connects to this face.

                }  // end if VU Face == this Face
            }  // end loop on VU's of pThisVertex

          // Every Face->Vertex must connect back to the face at least once
          bRtn &= SM_ASSERT_BOOLEAN_REPORT(13, SM_LEVEL_0, (lFaceConnections >= 1), _T("")) ;

        }  // end loop on all Vertices of this Face

    } // end Face-owned vertex classification (tests 12-13)

  // Check all connected Faceuses. Keep this at LEVEL_0 outside the 12/13 gate.
  {
    SmFaceuse *pFaceuse1, *pFaceuse2 ;
    GetFaceuses(pFaceuse1, pFaceuse2) ;
    if(pFaceuse1) { bRtn &= pFaceuse1->AssertValid(pAList, eTestLevel, SM_NO_WALK) ; }
    if(pFaceuse2) { bRtn &= pFaceuse2->AssertValid(pAList, eTestLevel, SM_NO_WALK) ; }
  }


  // double  dBrepTol = GetBrep() ? (double)GetBrep()->GetTolerance() : 0.0 ;
  double  dFaceTol = GetTolerance() ;

  /* obsolete */ /* 25 */ // Face Tolerance less than Brep Tol
  // bRtn &= SM_ASSERT_VALUE_REPORT(25, SM_LEVEL_0, dFaceTol >= dBrepTol - SM_EFF_ZERO, dBrepTol, dFaceTol, _T("")) ;

  /* obsolete */ /* 26 */ // Face Tolerance greater than 1000 times Brep Tol
  // bRtn &= SM_ASSERT_VALUE_REPORT(26, SM_LEVEL_0, dFaceTol <= 1000 * dBrepTol, 1000 * dBrepTol, dFaceTol, _T("")) ;

  /* 27 */ // Zero Area Face degenerates to a point location
  bRtn &= SM_ASSERT_VALUE_REPORT(27, SM_LEVEL_0, !m_pSurface->IsDegeneratePoint(dFaceTol/4.0, &m_vUVDomain), dFaceTol/4.0, SM_UNDEF_DOUBLE, _T("")) ;

  /* 28 */ // Zero Area Face degenerates to a curve shape
  bRtn &= SM_ASSERT_VALUE_REPORT(28, SM_LEVEL_0, !m_pSurface->IsDegenerateCurve(SM_EFF_ZERO_DEG, &m_vUVDomain, dFaceTol/4.0), dFaceTol/4.0, SM_UNDEF_DOUBLE, _T("")) ;

  /* 32 */ // Face has Coincient Vertices
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(32, SM_LEVEL_2, sm_AssertTestFace32(this) == TRUE, _T("")) ;

  /* 33 */ // Face has Coincient Edges
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(33, SM_LEVEL_2, sm_AssertTestFace33(this) == TRUE, _T("")) ;

  /* 34 */ // Face has Coincient Edges
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(34, SM_LEVEL_2, sm_AssertTestFace34(this) == TRUE, _T("")) ;

  /* 37 */ // Face InnerLoops must nest inside the OuterLoop and outside each other
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(37, SM_LEVEL_0, sm_AssertTestFace37(this) == TRUE, _T("")) ;

  /* 38 */ // Face Loops must be disjoint in the Face UVSpace
  //         a Face with no Surface has no UVSpace to check - AssertTest 3 reports it
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(38, SM_LEVEL_2, m_pSurface == NULL || sm_AssertTestFace38(this) == TRUE, _T("")) ;

  /* 39 */ // no Vertex may be shared by two Face Loops
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(39, SM_LEVEL_0, sm_AssertTestFace39(this) == TRUE, _T("")) ;

  // Note: 29 should happen before 31.  [B513]
  //  Not so fast, we have a counterexample.  [B530]
  //  Surface is a torus, and the Loops (Edges) in the inut file are simply
  //  two curves that go all the way around, both parallel to the big seam.
  //  There's no Edge on the other-direction seam.  So the CurveClassification of
  //  the seam curve in the horizontal (big) direction is UNK-UNK-UNK.
  //  But if there were an edge on that cross-seam, then the parallel CC
  //  Would be either UNK-UNK_UNK (if out) or EDGE-UNK-EDGE (if in),
  //  so you could tell.
  //  Then the other-direction CC might be U-U-[E|V]  [E|V]-U-[E|V]  [E|V]-U-U.
  //  That would say, add an Edge there (rule 31).
  //  Then the parallel-direction check would work.
  // So what we have to do is to combine these two tests, 29 and 31:
  //  They both do CurveClassifications along seam curves.
  //  Do both CC's and then figure out what exactly is going on.

  // locals
  SmCurveClassification sCrvClassU;
  SmCurveClassification sCrvClassV;
  SmSurfParamType eCrossedSeam;
  SmSurfParamType eMissingSeam;
  SmSurfParamType eNearMissSeam;

  // Test = FALSE when pFace->Edges intersects pFace->PeriodicSurface->Seam
  HasSeamProblem(sCrvClassU, 
                 sCrvClassV, 
                 eCrossedSeam, 
                 eMissingSeam, 
                 eNearMissSeam) ;

  /* 29 */ // Face OuterLoop boundaries cannot cross a periodic surface seam
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(29, SM_LEVEL_2, eCrossedSeam == SM_SP_NEITHER, _T("")) ;

  /* 31 */ // FaceSeams must be represented by Edges
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(31, SM_LEVEL_2, eMissingSeam == SM_SP_NEITHER, _T("")) ;

  /* 36 */ // FaceSeams must not have near miss
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(36, SM_LEVEL_2, eNearMissSeam == SM_SP_NEITHER, _T("")) ;

  /* 30 */ // Face's stored ZoneTol must equal the SmTol::Consistent Tolerance Model value
#ifdef SM_USE_OLDTOL
#ifdef SM_NMTLIB_7166
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(30, SM_LEVEL_2, sm_AssertTestFace30(this) == TRUE, _T("")) ;
#endif // SM_NMTLIB_7166
#endif // SM_USE_OLDTOL

  // when the face has a surface
  if(   m_pSurface
     && (eTestLevel != SM_LEVEL_GIVEN))
    {
      // Check Face->Surface
      bRtn &= m_pSurface->AssertValid(pAList, eTestLevel, SM_NO_WALK) ;

    } // end m_pSurface exists check

  // when asked - AssertValid for a topology graph traversal
  if(eWalkTree == SM_WALK)
    {
      bRtn &= SmBrep::AssertSubTopology( (SmTopology &)*this, pAList, eTestLevel) ;
      // bRtn &= SM_ASSERT_BOOLEAN_REPORT(20, SM_LEVEL_0, (SmBrep::AssertSubTopology( (SmTopology &)*this, pAList, eTestLevel)), _T("")) ;

    } // end asked to walk the tree check

  // all done
  // SM_ASSERT_MSG( bRtn, _T("SmFace::AssertValid(): Errors Found") );
  return( bRtn );

} // end SmFace::AssertValid

